pub(crate) struct PendingContactStep {
    pub(crate) problem: ContactProblem,
    pub(crate) warm_start: Vec<ContactImpulse>,
    pub(crate) solve_params: SolveParams,
    contact_frames: Vec<ContactFrame>,
    link_origins: Vec<Vector3<f64>>,
    old_base_momentum: Option<DVector<f64>>,
    predicted_velocity: DVector<f64>,
    applied_force: DVector<f64>,
    mass: DMatrix<f64>,
    offset: usize,
    robot_dof: usize,
    scene_slots: Vec<Option<usize>>,
    floating_com: Option<(f64, Vector3<f64>)>,
    gravity: Vector3<f64>,
    dt: f64,
}

#[derive(Debug)]
struct CachedContact {
    owners: (ContactOwner, ContactOwner),
    position: Vector3<f64>,
    normal: Vector3<f64>,
    impulse_world: Vector3<f64>,
    dt: f64,
}

fn warm_start_impulses(
    frames: &[ContactFrame],
    cache: &[CachedContact],
    dt: f64,
) -> Vec<ContactImpulse> {
    let mut used = vec![false; cache.len()];
    frames
        .iter()
        .map(|frame| {
            // The articulated Jacobian changes enough between steps that a
            // proximity match alone cannot safely carry its old impulse.
            if matches!(frame.owners.0, ContactOwner::Robot(_))
                || matches!(frame.owners.1, ContactOwner::Robot(_))
            {
                return ContactImpulse::default();
            }
            let nearest = cache
                .iter()
                .enumerate()
                .filter(|(index, old)| {
                    !used[*index]
                        && old.owners == frame.owners
                        && old.normal.dot(&frame.normal) > 0.94
                        && (old.position - frame.position).norm_squared() < 0.03_f64.powi(2)
                })
                .min_by(|(_, left), (_, right)| {
                    (left.position - frame.position)
                        .norm_squared()
                        .total_cmp(&(right.position - frame.position).norm_squared())
                });
            let Some((index, old)) = nearest else {
                return ContactImpulse::default();
            };
            used[index] = true;
            let world_impulse = old.impulse_world * (0.8 * dt / old.dt).clamp(0.0, 2.0);
            ContactImpulse {
                normal: world_impulse.dot(&frame.normal).max(0.0),
                tangents: [
                    world_impulse.dot(&frame.tangent_a),
                    world_impulse.dot(&frame.tangent_b),
                ],
            }
        })
        .collect()
}

/// Collision geometry attached to a free scene body.
#[derive(Debug, Clone, PartialEq)]
pub enum SceneCollider {
    /// A sphere in the body frame.
    Sphere {
        /// Sphere centre in body coordinates.
        center: Vector3<f64>,
        /// Positive sphere radius.
        radius: f64,
    },
    /// A z-axis capsule in an oriented body-local frame.
    Capsule {
        /// Capsule frame in body coordinates.
        origin: Isometry3<f64>,
        /// Half the length of the central segment.
        half_height: f64,
        /// Positive spherical border radius.
        radius: f64,
    },
    /// A z-axis circular cylinder in an oriented body-local frame.
    Cylinder {
        /// Cylinder frame in body coordinates.
        origin: Isometry3<f64>,
        /// Half the full cylinder height.
        half_height: f64,
        /// Positive circular radius.
        radius: f64,
    },
    /// A z-axis circular cone in an oriented body-local frame.
    Cone {
        /// Cone frame in body coordinates.
        origin: Isometry3<f64>,
        /// Half the full cone height from base to apex.
        half_height: f64,
        /// Positive base radius.
        radius: f64,
    },
    /// An oriented box in the body frame.
    Box {
        /// Shape frame in body coordinates.
        origin: Isometry3<f64>,
        /// Positive local half extents.
        half_extents: Vector3<f64>,
    },
    /// A convex hull in the body frame.
    Convex {
        /// Shape frame in body coordinates.
        origin: Isometry3<f64>,
        /// Prepared hull geometry.
        geometry: ConvexGeometry,
    },
    /// An indexed triangle mesh in the body frame.
    TriangleMesh {
        /// Shape frame in body coordinates.
        origin: Isometry3<f64>,
        /// Validated indexed triangle geometry.
        geometry: TriangleMeshGeometry,
    },
    /// A regular z-up heightfield in the body frame.
    HeightField {
        /// Shape frame in body coordinates.
        origin: Isometry3<f64>,
        /// Height samples and their precomputed triangle mesh.
        geometry: HeightFieldGeometry,
    },
    /// Indexed zero-thickness line segments in the body frame.
    Polyline {
        /// Shape frame in body coordinates.
        origin: Isometry3<f64>,
        /// Validated indexed line geometry.
        geometry: PolylineGeometry,
    },
}

/// One independent scene body, with mass and inertia about its origin.
#[derive(Debug, Clone, PartialEq)]
pub struct SceneBody {
    /// Body pose in world coordinates.
    pub pose: Isometry3<f64>,
    /// World-frame origin velocity.
    pub linear_velocity: Vector3<f64>,
    /// World-frame angular velocity.
    pub angular_velocity: Vector3<f64>,
    /// Mass in kilograms; zero is static, prescribed, or externally posed.
    pub mass: f64,
    /// Integrate prescribed velocities with zero inverse mass. Requires mass zero.
    pub kinematic: bool,
    /// Body-frame inertia about the origin.
    pub inertia: Matrix3<f64>,
    /// Persistent world-frame force at the body origin.
    pub force: Vector3<f64>,
    /// Body-attached collision shapes.
    pub colliders: Vec<SceneCollider>,
}

impl SceneBody {
    /// Build a solid cone from the world pose of its geometric center.
    /// The base is at local `-half_height`, the apex at `+half_height`.
    /// Body state is placed at the center of mass; the collider offset preserves
    /// the supplied shape pose, including for rotated or stationary cones.
    pub fn solid_cone(
        shape_pose: Isometry3<f64>,
        radius: f64,
        half_height: f64,
        mass: f64,
    ) -> Result<Self, ArticulatedWorldError> {
        let properties =
            crate::mass_properties::MassProperties::solid_cone(radius, half_height, mass)
                .map_err(|_| ArticulatedWorldError::InvalidInput)?;
        let norm = shape_pose.rotation.quaternion().norm_squared();
        if !norm.is_finite() || (norm - 1.0).abs() > 1e-5 {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        let center = properties.center_of_mass;
        Self::new(
            shape_pose * Isometry3::translation(center.x, center.y, center.z),
            mass,
            properties.inertia,
            vec![SceneCollider::Cone {
                origin: Isometry3::translation(-center.x, -center.y, -center.z),
                radius,
                half_height,
            }],
        )
    }

    /// Construct a stationary body with zero velocity and force.
    /// Empty collider lists are valid for bodies that only carry state or constraints.
    pub fn new(
        pose: Isometry3<f64>,
        mass: f64,
        inertia: Matrix3<f64>,
        colliders: Vec<SceneCollider>,
    ) -> Result<Self, ArticulatedWorldError> {
        if pose
            .translation
            .vector
            .iter()
            .any(|value| !value.is_finite())
            || pose.rotation.coords.iter().any(|value| !value.is_finite())
            || !mass.is_finite()
            || mass < 0.0
            || inertia.iter().any(|value| !value.is_finite())
            || (mass > 0.0
                && ((inertia - inertia.transpose()).norm() > 1e-8
                    || inertia
                        .symmetric_eigen()
                        .eigenvalues
                        .iter()
                        .any(|value| !value.is_finite() || *value <= 1e-12)))
            || colliders.iter().any(|collider| match collider {
                SceneCollider::Sphere { center, radius } => {
                    center.iter().any(|value| !value.is_finite())
                        || !radius.is_finite()
                        || *radius <= 0.0
                }
                SceneCollider::Box {
                    origin,
                    half_extents,
                } => {
                    origin
                        .translation
                        .vector
                        .iter()
                        .any(|value| !value.is_finite())
                        || origin
                            .rotation
                            .coords
                            .iter()
                            .any(|value| !value.is_finite())
                        || half_extents
                            .iter()
                            .any(|value| !value.is_finite() || *value <= 0.0)
                }
                SceneCollider::Capsule {
                    origin,
                    half_height,
                    radius,
                } => {
                    origin
                        .translation
                        .vector
                        .iter()
                        .any(|value| !value.is_finite())
                        || origin
                            .rotation
                            .coords
                            .iter()
                            .any(|value| !value.is_finite())
                        || !half_height.is_finite()
                        || *half_height < 0.0
                        || !radius.is_finite()
                        || *radius <= 0.0
                }
                SceneCollider::Cylinder {
                    origin,
                    half_height,
                    radius,
                }
                | SceneCollider::Cone {
                    origin,
                    half_height,
                    radius,
                } => {
                    origin
                        .translation
                        .vector
                        .iter()
                        .any(|value| !value.is_finite())
                        || origin
                            .rotation
                            .coords
                            .iter()
                            .any(|value| !value.is_finite())
                        || !half_height.is_finite()
                        || *half_height <= 0.0
                        || !radius.is_finite()
                        || *radius <= 0.0
                }
                SceneCollider::Convex { origin, .. }
                | SceneCollider::TriangleMesh { origin, .. }
                | SceneCollider::HeightField { origin, .. }
                | SceneCollider::Polyline { origin, .. } => {
                    origin
                        .translation
                        .vector
                        .iter()
                        .any(|value| !value.is_finite())
                        || origin
                            .rotation
                            .coords
                            .iter()
                            .any(|value| !value.is_finite())
                }
            })
        {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        Ok(Self {
            pose,
            linear_velocity: Vector3::zeros(),
            angular_velocity: Vector3::zeros(),
            mass,
            kinematic: false,
            inertia,
            force: Vector3::zeros(),
            colliders,
        })
    }
}

type WorldHull = (
    usize,
    Vec<Vector3<f64>>,
    Vec<Vector3<f64>>,
    Vec<Vector3<f64>>,
    ColliderMaterial,
);
type WorldCapsule = (
    usize,
    [Vector3<f64>; 2],
    Vector3<f64>,
    f64,
    ColliderMaterial,
);

#[derive(Debug, Clone, Copy)]
struct WorldBounds {
    scene_body: Option<usize>,
    lower: Vector3<f64>,
    upper: Vector3<f64>,
}

impl WorldBounds {
    fn overlaps(self, other: Self) -> bool {
        (0..3).all(|axis| {
            self.lower[axis] <= other.upper[axis] && other.lower[axis] <= self.upper[axis]
        })
    }
}

struct SceneMeshInstance<'a> {
    body_index: usize,
    frame: Isometry3<f64>,
    geometry: &'a TriangleMeshGeometry,
    material: ColliderMaterial,
}

struct ScenePolylineInstance<'a> {
    body_index: usize,
    frame: Isometry3<f64>,
    geometry: &'a PolylineGeometry,
    material: ColliderMaterial,
}

fn bounds_from_points(
    scene_body: Option<usize>,
    points: impl IntoIterator<Item = Vector3<f64>>,
    radius: f64,
) -> Option<WorldBounds> {
    let mut points = points.into_iter();
    let first = points.next()?;
    let (lower, upper) = points.fold((first, first), |(lower, upper), point| {
        (lower.inf(&point), upper.sup(&point))
    });
    Some(WorldBounds {
        scene_body,
        lower: lower - Vector3::repeat(radius),
        upper: upper + Vector3::repeat(radius),
    })
}

fn transform_bounds(
    scene_body: Option<usize>,
    frame: &Isometry3<f64>,
    lower: Vector3<f64>,
    upper: Vector3<f64>,
) -> WorldBounds {
    let corners = [-1.0, 1.0].into_iter().flat_map(|x| {
        [-1.0, 1.0].into_iter().flat_map(move |y| {
            [-1.0, 1.0].into_iter().map(move |z| {
                let local = Vector3::new(
                    if x < 0.0 { lower.x } else { upper.x },
                    if y < 0.0 { lower.y } else { upper.y },
                    if z < 0.0 { lower.z } else { upper.z },
                );
                frame.transform_point(&Point3::from(local)).coords
            })
        })
    });
    bounds_from_points(scene_body, corners, 0.0)
        .unwrap_or_else(|| unreachable!("an AABB always has eight corners"))
}

fn inverse_transform_bounds(
    frame: &Isometry3<f64>,
    bounds: WorldBounds,
) -> (Vector3<f64>, Vector3<f64>) {
    let corners = [-1.0, 1.0].into_iter().flat_map(|x| {
        [-1.0, 1.0].into_iter().flat_map(move |y| {
            [-1.0, 1.0].into_iter().map(move |z| {
                let world = Vector3::new(
                    if x < 0.0 {
                        bounds.lower.x
                    } else {
                        bounds.upper.x
                    },
                    if y < 0.0 {
                        bounds.lower.y
                    } else {
                        bounds.upper.y
                    },
                    if z < 0.0 {
                        bounds.lower.z
                    } else {
                        bounds.upper.z
                    },
                );
                frame.inverse_transform_point(&Point3::from(world)).coords
            })
        })
    });
    let local = bounds_from_points(None, corners, 0.0)
        .unwrap_or_else(|| unreachable!("an AABB always has eight corners"));
    (local.lower, local.upper)
}

fn append_scene_mesh_hulls(
    hulls: &mut Vec<WorldHull>,
    body_index: usize,
    frame: &Isometry3<f64>,
    geometry: &TriangleMeshGeometry,
    triangle_indices: &[usize],
    material: ColliderMaterial,
) {
    hulls.extend(triangle_indices.iter().filter_map(|&index| {
        let prism = geometry.prisms().get(index)?;
        let vertices = prism
            .vertices
            .iter()
            .map(|vertex| frame.transform_point(&Point3::from(*vertex)).coords)
            .collect();
        let normals = prism
            .face_normals
            .iter()
            .map(|normal| frame.rotation * normal)
            .collect();
        let edges = prism
            .edge_directions
            .iter()
            .map(|edge| frame.rotation * edge)
            .collect();
        Some((body_index, vertices, normals, edges, material))
    }));
}

fn append_scene_polyline_segments(
    capsules: &mut Vec<WorldCapsule>,
    instance: &ScenePolylineInstance<'_>,
    segment_indices: &[usize],
) {
    capsules.extend(segment_indices.iter().filter_map(|&index| {
        let endpoints = instance
            .geometry
            .segment_vertices(index)?
            .map(|vertex| instance.frame.transform_point(&Point3::from(vertex)).coords);
        let axis = (endpoints[1] - endpoints[0]).normalize();
        Some((instance.body_index, endpoints, axis, 0.0, instance.material))
    }));
}

fn scene_point_row(
    slot: Option<usize>,
    body_origin: Vector3<f64>,
    world_point: Vector3<f64>,
    direction: Vector3<f64>,
    total_dof: usize,
) -> DVector<f64> {
    let mut row = DVector::zeros(total_dof);
    if let Some(slot) = slot {
        let angular = (world_point - body_origin).cross(&direction);
        for axis in 0..3 {
            row[slot + axis] = direction[axis];
            row[slot + axis + 3] = angular[axis];
        }
    }
    row
}

fn append_bilateral_error_row(
    axis: DVector<f64>,
    error: f64,
    inverse_mass: &DMatrix<f64>,
    dt: f64,
    solve_params: SolveParams,
    contacts: &mut Vec<ContactConstraint>,
    warm_start: &mut Vec<ContactImpulse>,
) -> Result<(), ArticulatedWorldError> {
    let effective_inverse_mass = axis.dot(&(inverse_mass * &axis));
    if !effective_inverse_mass.is_finite() {
        return Err(ArticulatedWorldError::NumericalInstability);
    }
    if effective_inverse_mass <= 1e-12 {
        if error.abs() > 1e-9 {
            return Err(ContactSolveError::SingularContact.into());
        }
        return Ok(());
    }
    let target_speed = -solve_params.position_gain * error / dt;
    if !target_speed.is_finite() {
        return Err(ArticulatedWorldError::InvalidInput);
    }
    contacts.push(ContactConstraint::bilateral_axis(
        axis,
        target_speed.clamp(
            -solve_params.max_correction_speed,
            solve_params.max_correction_speed,
        ),
    ));
    warm_start.push(ContactImpulse::default());
    Ok(())
}

fn assigned_material(
    materials: &[ColliderMaterial],
    index: usize,
    default_material: ColliderMaterial,
) -> ColliderMaterial {
    materials.get(index).copied().unwrap_or(default_material)
}

fn assign_material(
    materials: &mut Vec<ColliderMaterial>,
    shape_count: usize,
    index: usize,
    material: ColliderMaterial,
    default_material: ColliderMaterial,
) -> bool {
    if index >= shape_count || !material.is_valid() {
        return false;
    }
    materials.resize(shape_count, default_material);
    materials[index] = material;
    true
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContactOwner {
    Ground,
    Robot(usize),
    Scene(usize),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContactGeometry {
    Hull,
    Sphere,
    RoundedHull,
    Analytic,
}

#[derive(Debug, Clone, Copy)]
enum WorldAnalyticShape {
    Cylinder {
        center: Vector3<f64>,
        axis: Vector3<f64>,
        half_height: f64,
        radius: f64,
    },
    Cone {
        center: Vector3<f64>,
        axis: Vector3<f64>,
        half_height: f64,
        radius: f64,
    },
}

impl WorldAnalyticShape {
    fn center(self) -> Vector3<f64> {
        match self {
            Self::Cylinder { center, .. } | Self::Cone { center, .. } => center,
        }
    }

    fn axis(self) -> Vector3<f64> {
        match self {
            Self::Cylinder { axis, .. } | Self::Cone { axis, .. } => axis,
        }
    }

    fn support(self, direction: Vector3<f64>) -> Vector3<f64> {
        match self {
            Self::Cylinder {
                center,
                axis,
                half_height,
                radius,
            } => cylinder_support(center, axis, half_height, radius, direction),
            Self::Cone {
                center,
                axis,
                half_height,
                radius,
            } => cone_support(center, axis, half_height, radius, direction),
        }
    }

    fn sphere_contact(
        self,
        sphere_center: Vector3<f64>,
        sphere_radius: f64,
    ) -> Option<ConvexContact> {
        match self {
            Self::Cylinder {
                center,
                axis,
                half_height,
                radius,
            } => cylinder_sphere_contact(
                center,
                axis,
                half_height,
                radius,
                sphere_center,
                sphere_radius,
            ),
            Self::Cone {
                center,
                axis,
                half_height,
                radius,
            } => cone_sphere_contact(
                center,
                axis,
                half_height,
                radius,
                sphere_center,
                sphere_radius,
            ),
        }
    }

    fn bounds(self) -> (Vector3<f64>, Vector3<f64>) {
        (
            Vector3::new(
                self.support(-Vector3::x()).x,
                self.support(-Vector3::y()).y,
                self.support(-Vector3::z()).z,
            ),
            Vector3::new(
                self.support(Vector3::x()).x,
                self.support(Vector3::y()).y,
                self.support(Vector3::z()).z,
            ),
        )
    }

    #[cfg(feature = "gpu-contact")]
    fn gpu(self) -> GpuAnalyticShape {
        let pack_axis = |axis: Vector3<f64>| [axis.x as f32, axis.y as f32, axis.z as f32];
        match self {
            Self::Cylinder {
                axis,
                half_height,
                radius,
                ..
            } => GpuAnalyticShape::Cylinder {
                axis: pack_axis(axis),
                half_height: half_height as f32,
                radius: radius as f32,
            },
            Self::Cone {
                axis,
                half_height,
                radius,
                ..
            } => GpuAnalyticShape::Cone {
                axis: pack_axis(axis),
                half_height: half_height as f32,
                radius: radius as f32,
            },
        }
    }

    fn ground_points(self) -> [Vector3<f64>; 4] {
        let down = -Vector3::z();
        if let Self::Cylinder {
            center,
            axis,
            half_height,
            radius,
        } = self
        {
            let axial = down.dot(&axis);
            let cap_center = center
                + axis
                    * if axial >= 0.0 {
                        half_height
                    } else {
                        -half_height
                    };
            let radial = down - axis * axial;
            if radial.norm_squared() > 1e-8 {
                let point = cap_center + radial.normalize() * radius;
                return [point; 4];
            }
            let reference = if axis.x.abs() < 0.9 {
                Vector3::x()
            } else {
                Vector3::y()
            };
            let tangent_a = axis.cross(&reference).normalize();
            let tangent_b = axis.cross(&tangent_a).normalize();
            return [
                cap_center + tangent_a * radius,
                cap_center - tangent_a * radius,
                cap_center + tangent_b * radius,
                cap_center - tangent_b * radius,
            ];
        }
        [Vector3::x(), -Vector3::x(), Vector3::y(), -Vector3::y()]
            .map(|tangent| self.support(down + tangent * 1e-7))
    }
}

struct WorldContactShape {
    owner: ContactOwner,
    vertices: Vec<Vector3<f64>>,
    normals: Vec<Vector3<f64>>,
    edges: Vec<Vector3<f64>>,
    radius: f64,
    geometry: ContactGeometry,
    analytic: Option<WorldAnalyticShape>,
    mesh_hull: bool,
    material: ColliderMaterial,
}

impl WorldContactShape {
    fn center(&self) -> Vector3<f64> {
        self.analytic.map_or_else(
            || self.vertices.iter().copied().sum::<Vector3<f64>>() / self.vertices.len() as f64,
            WorldAnalyticShape::center,
        )
    }

    fn support(&self, direction: Vector3<f64>) -> Vector3<f64> {
        self.analytic.map_or_else(
            || {
                let core = self
                    .vertices
                    .iter()
                    .max_by(|left, right| left.dot(&direction).total_cmp(&right.dot(&direction)))
                    .copied()
                    .unwrap_or_else(Vector3::zeros);
                core + direction.try_normalize(1e-12).unwrap_or_else(Vector3::x) * self.radius
            },
            |shape| shape.support(direction),
        )
    }

    fn bounds(&self) -> (Vector3<f64>, Vector3<f64>) {
        if let Some(analytic) = self.analytic {
            analytic.bounds()
        } else {
            self.vertices.iter().fold(
                (
                    Vector3::repeat(f64::INFINITY),
                    Vector3::repeat(-f64::INFINITY),
                ),
                |(min, max), point| (min.inf(point), max.sup(point)),
            )
        }
    }
}

fn mesh_sphere_contact(
    mesh: &WorldContactShape,
    sphere: &WorldContactShape,
) -> Option<ConvexContact> {
    if !mesh.mesh_hull || sphere.geometry != ContactGeometry::Sphere {
        return None;
    }
    let [a, b, c] =
        core::array::from_fn(|index| (mesh.vertices[index] + mesh.vertices[index + 3]) * 0.5);
    let normal = (b - a).cross(&(c - a)).try_normalize(1e-12)?;
    let center = sphere.vertices[0];
    let signed_distance = (center - a).dot(&normal);
    let projected = center - normal * signed_distance;
    let edges = [(a, b), (b, c), (c, a)];
    let scale = edges
        .iter()
        .map(|(start, end)| (end - start).norm_squared())
        .fold(1.0_f64, f64::max);
    let face = !edges.iter().any(|(start, end)| {
        normal.dot(&(end - start).cross(&(projected - start))) < -scale * 1e-10
    });
    let (surface, outward, depth) = if face {
        let depth = sphere.radius + TRIANGLE_HALF_THICKNESS - signed_distance.abs();
        let outward = normal * if signed_distance >= 0.0 { 1.0 } else { -1.0 };
        (
            projected + outward * TRIANGLE_HALF_THICKNESS,
            outward,
            depth,
        )
    } else {
        let closest = edges
            .iter()
            .map(|(start, end)| {
                let edge = end - start;
                let t = ((projected - start).dot(&edge) / edge.norm_squared()).clamp(0.0, 1.0);
                start + edge * t
            })
            .min_by(|a, b| {
                (a - projected)
                    .norm_squared()
                    .total_cmp(&(b - projected).norm_squared())
            })?;
        let surface = closest
            + normal * signed_distance.clamp(-TRIANGLE_HALF_THICKNESS, TRIANGLE_HALF_THICKNESS);
        let delta = center - surface;
        let distance = delta.norm();
        let outward = if distance > 1e-12 {
            delta / distance
        } else {
            normal * if signed_distance >= 0.0 { 1.0 } else { -1.0 }
        };
        (surface, outward, sphere.radius - distance)
    };
    if depth < 0.0 {
        return None;
    }
    let sphere_witness = center - outward * sphere.radius;
    Some(ConvexContact {
        point: (surface + sphere_witness) * 0.5,
        normal: outward,
        penetration: depth,
    })
}

fn mesh_analytic_contact(
    mesh: &WorldContactShape,
    analytic: &WorldContactShape,
) -> Option<ConvexContact> {
    let shape = analytic.analytic?;
    if !mesh.mesh_hull || mesh.vertices.len() != 6 {
        return None;
    }
    let [a, b, c] =
        core::array::from_fn(|index| (mesh.vertices[index] + mesh.vertices[index + 3]) * 0.5);
    let face = (b - a).cross(&(c - a)).try_normalize(1e-12)?;
    let _ = support_map_contact(
        analytic.center(),
        |direction| analytic.support(direction),
        mesh.center(),
        |direction| mesh.support(direction),
    )?;

    let center = shape.center();
    let projected = center - face * (center - a).dot(&face);
    let edges = [(a, b), (b, c), (c, a)];
    let scale = edges
        .iter()
        .map(|(start, end)| (end - start).norm_squared())
        .fold(1.0_f64, f64::max);
    let inside = !edges
        .iter()
        .any(|(start, end)| face.dot(&(end - start).cross(&(projected - start))) < -scale * 1e-10);
    let closest = if inside {
        projected
    } else {
        edges
            .iter()
            .map(|(start, end)| {
                let edge = end - start;
                let t = ((projected - start).dot(&edge) / edge.norm_squared()).clamp(0.0, 1.0);
                start + edge * t
            })
            .min_by(|left, right| {
                (left - projected)
                    .norm_squared()
                    .total_cmp(&(right - projected).norm_squared())
            })?
    };
    let axis = shape.axis();
    let mut candidates = vec![face];
    if axis.dot(&face).abs() < 0.99 {
        candidates.push(axis);
        candidates.push(center - closest);
        candidates.extend(edges.iter().map(|(start, end)| (end - start).cross(&axis)));
    }
    let mut best_depth = f64::INFINITY;
    let mut best_normal = face;
    for candidate in candidates {
        let Some(direction) = candidate.try_normalize(1e-12) else {
            continue;
        };
        let triangle_min = [a, b, c]
            .into_iter()
            .map(|vertex| vertex.dot(&direction))
            .fold(f64::INFINITY, f64::min);
        let triangle_max = [a, b, c]
            .into_iter()
            .map(|vertex| vertex.dot(&direction))
            .fold(f64::NEG_INFINITY, f64::max);
        let shape_min = shape.support(-direction).dot(&direction);
        let shape_max = shape.support(direction).dot(&direction);
        let forward = triangle_max - shape_min;
        let backward = shape_max - triangle_min;
        let depth = forward.min(backward);
        if depth < -1e-5 {
            return None;
        }
        if depth < best_depth {
            best_depth = depth;
            best_normal = direction * if forward < backward { 1.0 } else { -1.0 };
        }
    }
    let witness = shape.support(-best_normal);
    Some(ConvexContact {
        point: (closest + witness) * 0.5,
        normal: best_normal,
        penetration: best_depth.max(0.0),
    })
}

struct ContactRowContext<'a> {
    articulation: &'a Articulation,
    pose: &'a ArticulationPose,
    floating: bool,
    scene_bodies: &'a [SceneBody],
    scene_slots: &'a [Option<usize>],
    total_dof: usize,
}

impl ContactRowContext<'_> {
    fn owner_row(
        &self,
        owner: ContactOwner,
        world_point: Vector3<f64>,
        direction: Vector3<f64>,
    ) -> Result<DVector<f64>, ArticulatedWorldError> {
        match owner {
            ContactOwner::Ground => Ok(DVector::zeros(self.total_dof)),
            ContactOwner::Robot(link) => {
                let local = self.pose.links[link]
                    .inverse_transform_point(&Point3::from(world_point))
                    .coords;
                let (jacobian, _) = self.articulation.generalized_point_jacobians(
                    self.pose,
                    link,
                    local,
                    self.floating,
                )?;
                let robot_row = jacobian.transpose() * direction;
                let mut row = DVector::zeros(self.total_dof);
                for index in 0..robot_row.len() {
                    row[index] = robot_row[index];
                }
                Ok(row)
            }
            ContactOwner::Scene(body_index) => Ok(scene_point_row(
                self.scene_slots[body_index],
                self.scene_bodies[body_index].pose.translation.vector,
                world_point,
                direction,
                self.total_dof,
            )),
        }
    }
}

/// Fixed-step parameters for the articulated reference world.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ArticulatedWorldParams {
    /// Gravity in world coordinates, metres per second squared.
    pub gravity: [f64; 3],
    /// Half-extent of the finite ground in X and Y, metres.
    pub ground_half_extent: f64,
    /// Contact friction coefficient.
    pub friction: f64,
    /// Non-negative normal coefficient of restitution.
    pub restitution: f64,
    /// Maximum integration substep, seconds.
    pub max_substep: f64,
    /// Projected contact solver sweeps per substep.
    pub solver_iterations: usize,
    /// Automatic sleep and wake thresholds for independent scene bodies.
    pub sleep: SleepSettings,
}

impl Default for ArticulatedWorldParams {
    fn default() -> Self {
        Self {
            gravity: [0.0, 0.0, -9.81],
            ground_half_extent: 50.0,
            friction: 1.0,
            restitution: 0.0,
            max_substep: 0.001,
            solver_iterations: 12,
            sleep: SleepSettings::default(),
        }
    }
}

/// Invalid articulated state or a failed dynamics/contact solve.
#[derive(Debug, thiserror::Error)]
pub enum ArticulatedWorldError {
    /// Invalid world configuration, torque, or time step.
    #[error("invalid articulated world input")]
    InvalidInput,
    /// The fixed-root resident GPU path cannot represent a world feature yet.
    #[cfg(feature = "gpu-contact")]
    #[error("unsupported resident GPU articulated feature: {0}")]
    GpuResidentUnsupported(&'static str),
    /// The generalized inertia cannot be inverted.
    #[error("singular articulated inertia")]
    SingularMass,
    /// Predicted or solved generalized velocity exceeded a finite safety bound.
    #[error("articulated dynamics became numerically unstable")]
    NumericalInstability,
    /// Tree or state evaluation failed.
    #[error("articulation evaluation failed: {0}")]
    Articulation(#[from] ArticulationError),
    /// Contact impulse solve failed.
    #[error("articulated contact solve failed: {0}")]
    Contact(#[from] ContactSolveError),
    /// GPU collision detection failed.
    #[cfg(feature = "gpu-contact")]
    #[error("articulated GPU collision failed: {0}")]
    Gpu(#[from] ContactPipelineError),
    /// GPU contact impulse solve failed.
    #[cfg(feature = "gpu-contact")]
    #[error("articulated GPU contact solve failed: {0}")]
    GpuSolve(#[from] GpuContactSolveError),
    /// GPU generalized mass assembly or inversion failed.
    #[cfg(feature = "gpu-contact")]
    #[error("articulated GPU mass solve failed: {0}")]
    GpuMass(#[from] crate::gpu_articulated_mass::GpuArticulatedMassError),
}

/// Per-coordinate position and velocity drive, with a motor-only effort cap.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct JointMotor {
    /// Desired generalized position. None selects velocity-only control.
    pub position_target: Option<f64>,
    /// Desired generalized velocity in radians/s or m/s.
    pub velocity_target: f64,
    /// Position error gain in generalized force per coordinate.
    pub stiffness: f64,
    /// Velocity error gain in generalized force per coordinate speed.
    pub damping: f64,
    /// Maximum absolute motor force or torque. External input is not capped.
    pub max_force: f64,
}

impl JointMotor {
    fn is_valid(self) -> bool {
        self.position_target.is_none_or(f64::is_finite)
            && self.velocity_target.is_finite()
            && self.stiffness.is_finite()
            && self.stiffness >= 0.0
            && self.damping.is_finite()
            && self.damping >= 0.0
            && self.max_force.is_finite()
            && self.max_force >= 0.0
    }

    fn force(self, position: f64, velocity: f64) -> Option<f64> {
        let position_error = self.position_target.map_or(0.0, |target| target - position);
        let value =
            self.stiffness * position_error + self.damping * (self.velocity_target - velocity);
        value
            .is_finite()
            .then(|| value.clamp(-self.max_force, self.max_force))
    }
}

/// Uncapped passive spring and viscous damping on a generalized coordinate.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct JointPassive {
    /// Spring force per unit displacement from the rest position.
    pub stiffness: f64,
    /// Viscous force per unit generalized speed.
    pub damping: f64,
    /// Position where the spring force is zero.
    pub rest_position: f64,
}

impl Default for JointPassive {
    fn default() -> Self {
        Self {
            stiffness: 0.0,
            damping: 0.0,
            rest_position: 0.0,
        }
    }
}

impl JointPassive {
    fn is_valid(self) -> bool {
        self.stiffness.is_finite()
            && self.stiffness >= 0.0
            && self.damping.is_finite()
            && self.damping >= 0.0
            && self.rest_position.is_finite()
    }

    fn force(self, position: f64, velocity: f64) -> Option<f64> {
        let force = self.stiffness * (self.rest_position - position) - self.damping * velocity;
        force.is_finite().then_some(force)
    }
}

/// Nonlinear spring and damping terms on one generalized coordinate.
#[derive(Debug, Clone, Copy, Default, PartialEq)]
pub struct JointNonlinearPassive {
    /// Quadratic spring coefficient for displacement from rest.
    pub spring_quadratic: f64,
    /// Cubic spring coefficient for displacement from rest.
    pub spring_cubic: f64,
    /// Velocity-times-absolute-velocity damping coefficient.
    pub damping_quadratic: f64,
    /// Cubic damping coefficient.
    pub damping_cubic: f64,
}

impl JointNonlinearPassive {
    fn is_valid(self) -> bool {
        self.spring_quadratic.is_finite()
            && self.spring_cubic.is_finite()
            && self.damping_quadratic.is_finite()
            && self.damping_cubic.is_finite()
    }

    fn force_and_tangents(self, displacement: f64, velocity: f64) -> Option<(f64, f64, f64)> {
        let spring =
            self.spring_quadratic * displacement.powi(2) + self.spring_cubic * displacement.powi(3);
        let damping = self.damping_quadratic * velocity * velocity.abs()
            + self.damping_cubic * velocity.powi(3);
        let spring_tangent = 2.0 * self.spring_quadratic * displacement
            + 3.0 * self.spring_cubic * displacement.powi(2);
        let damping_tangent = 2.0 * self.damping_quadratic * velocity.abs()
            + 3.0 * self.damping_cubic * velocity.powi(2);
        [spring, damping, spring_tangent, damping_tangent]
            .iter()
            .all(|value| value.is_finite())
            .then_some((-spring - damping, spring_tangent, damping_tangent))
    }
}

/// Holonomic relation `follower = multiplier * source + offset` between slots.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct JointCoupling {
    /// Generalized coordinate driving the relation.
    pub source: usize,
    /// Generalized coordinate constrained by the relation.
    pub follower: usize,
    /// Follower displacement per source displacement.
    pub multiplier: f64,
    /// Follower position at a zero source position.
    pub offset: f64,
}

impl JointCoupling {
    fn is_valid(self, dof: usize) -> bool {
        self.source < dof
            && self.follower < dof
            && self.source != self.follower
            && self.multiplier.is_finite()
            && self.multiplier != 0.0
            && self.offset.is_finite()
    }
}

/// MJCF-style quartic equality between scalar generalized coordinates.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct JointPolynomialCoupling {
    /// Generalized coordinate constrained by the polynomial.
    pub follower: usize,
    /// Driving coordinate, or None to lock the follower to a constant.
    pub source: Option<usize>,
    /// Coefficients from constant through quartic order.
    pub coefficients: [f64; 5],
    /// Follower position in the reference configuration.
    pub follower_reference: f64,
    /// Source position in the reference configuration.
    pub source_reference: f64,
}

/// Ball constraint between link-local points, or a link point and the world.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LinkPointConstraint {
    /// First link index in the articulation.
    pub link_a: usize,
    /// Point in the first link's local frame.
    pub point_a: [f64; 3],
    /// Second link index, or None for a fixed world-space point.
    pub link_b: Option<usize>,
    /// Point in the second link's local frame, or in world space when link_b is None.
    pub point_b: [f64; 3],
}

impl LinkPointConstraint {
    pub(crate) fn is_valid(self, link_count: usize) -> bool {
        self.link_a < link_count
            && self
                .link_b
                .is_none_or(|link| link < link_count && link != self.link_a)
            && self
                .point_a
                .iter()
                .chain(self.point_b.iter())
                .all(|value| value.is_finite())
    }
}

/// Fixed constraint between link-local frames, or a link frame and the world.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LinkFixedConstraint {
    /// First link index in the articulation.
    pub link_a: usize,
    /// Frame in the first link's local coordinates.
    pub frame_a: Isometry3<f64>,
    /// Second link index, or None for a fixed world-space frame.
    pub link_b: Option<usize>,
    /// Frame in the second link's local coordinates, or in world space.
    pub frame_b: Isometry3<f64>,
}

impl LinkFixedConstraint {
    pub(crate) fn is_valid(self, link_count: usize) -> bool {
        let finite = |frame: Isometry3<f64>| {
            frame
                .translation
                .vector
                .iter()
                .all(|value| value.is_finite())
                && frame
                    .rotation
                    .quaternion()
                    .coords
                    .iter()
                    .all(|value| value.is_finite())
        };
        self.link_a < link_count
            && self
                .link_b
                .is_none_or(|link| link < link_count && link != self.link_a)
            && finite(self.frame_a)
            && finite(self.frame_b)
    }
}

/// Ball constraint between a link-local point and a scene-body-local point.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LinkScenePointConstraint {
    /// Link index in the articulation.
    pub link: usize,
    /// Point in link-local coordinates.
    pub link_point: [f64; 3],
    /// Scene body index.
    pub body: usize,
    /// Point in scene-body-local coordinates.
    pub body_point: [f64; 3],
}

impl LinkScenePointConstraint {
    fn is_valid(self, link_count: usize, body_count: usize) -> bool {
        self.link < link_count
            && self.body < body_count
            && self
                .link_point
                .iter()
                .chain(self.body_point.iter())
                .all(|value| value.is_finite())
    }
}

/// Fixed constraint between link-local and scene-body-local frames.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LinkSceneFixedConstraint {
    /// Link index in the articulation.
    pub link: usize,
    /// Frame in link-local coordinates.
    pub link_frame: Isometry3<f64>,
    /// Scene body index.
    pub body: usize,
    /// Frame in scene-body-local coordinates.
    pub body_frame: Isometry3<f64>,
}

impl LinkSceneFixedConstraint {
    fn is_valid(self, link_count: usize, body_count: usize) -> bool {
        let finite = |frame: Isometry3<f64>| {
            frame
                .translation
                .vector
                .iter()
                .all(|value| value.is_finite())
                && frame.rotation.coords.iter().all(|value| value.is_finite())
        };
        self.link < link_count
            && self.body < body_count
            && finite(self.link_frame)
            && finite(self.body_frame)
    }
}

impl JointPolynomialCoupling {
    pub(crate) fn is_valid(self, dof: usize) -> bool {
        self.follower < dof
            && self
                .source
                .is_none_or(|source| source < dof && source != self.follower)
            && self.coefficients.iter().all(|value| value.is_finite())
            && self.follower_reference.is_finite()
            && self.source_reference.is_finite()
    }

    fn value_and_derivative(self, position: f64) -> Option<(f64, f64)> {
        let x = position - self.source_reference;
        let [a0, a1, a2, a3, a4] = self.coefficients;
        let value = ((((a4 * x + a3) * x + a2) * x + a1) * x) + a0;
        let derivative = (((4.0 * a4 * x + 3.0 * a3) * x + 2.0 * a2) * x) + a1;
        (value.is_finite() && derivative.is_finite()).then_some((value, derivative))
    }
}

/// Persistent world-frame force and torque about a link center of mass.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LinkExternalLoad {
    /// Force in newtons, expressed in world coordinates.
    pub force: Vector3<f64>,
    /// Torque in newton-metres about the link center of mass, world frame.
    pub torque: Vector3<f64>,
    /// Multiplier for this link's gravity force.
    pub gravity_scale: f64,
}

/// World-space velocity of a point attached to an articulated link.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LinkTwist {
    /// Linear velocity of the selected point in metres per second.
    pub linear: Vector3<f64>,
    /// Angular velocity of the link in radians per second.
    pub angular: Vector3<f64>,
}

/// World-space acceleration of a point attached to an articulated link.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LinkAcceleration {
    /// Linear acceleration of the selected point in metres per second squared.
    pub linear: Vector3<f64>,
    /// Angular acceleration of the link in radians per second squared.
    pub angular: Vector3<f64>,
}

/// Ideal link-frame inertial sensor reading without noise or bias.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LinkImuReading {
    /// Proper acceleration at the sensor point, in the link frame.
    pub specific_force: Vector3<f64>,
    /// Angular velocity in the link frame.
    pub angular_velocity: Vector3<f64>,
    /// Angular acceleration in the link frame.
    pub angular_acceleration: Vector3<f64>,
}

impl Default for LinkExternalLoad {
    fn default() -> Self {
        Self {
            force: Vector3::zeros(),
            torque: Vector3::zeros(),
            gravity_scale: 1.0,
        }
    }
}

impl LinkExternalLoad {
    fn is_valid(self) -> bool {
        self.force.iter().all(|value| value.is_finite())
            && self.torque.iter().all(|value| value.is_finite())
            && self.gravity_scale.is_finite()
    }
}

/// Restorable dynamic state for one articulated environment.
