    /// Validate a fixed-base world, including a fully fixed root.
    pub fn new(
        articulation: Articulation,
        root_pose: Isometry3<f64>,
        colliders: Vec<LinkSphere>,
        params: ArticulatedWorldParams,
    ) -> Result<Self, ArticulatedWorldError> {
        Self::new_with_mode(articulation, root_pose, colliders, params, false)
    }

    /// Validate an articulated world with a dynamically floating root.
    pub fn new_floating(
        articulation: Articulation,
        root_pose: Isometry3<f64>,
        colliders: Vec<LinkSphere>,
        params: ArticulatedWorldParams,
    ) -> Result<Self, ArticulatedWorldError> {
        Self::new_with_mode(articulation, root_pose, colliders, params, true)
    }

    fn new_with_mode(
        articulation: Articulation,
        root_pose: Isometry3<f64>,
        colliders: Vec<LinkSphere>,
        params: ArticulatedWorldParams,
        floating: bool,
    ) -> Result<Self, ArticulatedWorldError> {
        if root_pose
            .translation
            .vector
            .iter()
            .any(|value| !value.is_finite())
            || root_pose
                .rotation
                .coords
                .iter()
                .any(|value| !value.is_finite())
            || params.gravity.iter().any(|value| !value.is_finite())
            || !params.ground_half_extent.is_finite()
            || params.ground_half_extent <= 0.0
            || !params.friction.is_finite()
            || params.friction < 0.0
            || !params.restitution.is_finite()
            || params.restitution < 0.0
            || !params.max_substep.is_finite()
            || params.max_substep <= 0.0
            || params.solver_iterations == 0
            || !params.sleep.is_valid()
            || colliders.iter().any(|collider| {
                collider.link >= articulation.link_count()
                    || collider.center.iter().any(|value| !value.is_finite())
                    || !collider.radius.is_finite()
                    || collider.radius <= 0.0
            })
        {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        let dof = articulation.dof();
        let link_count = articulation.link_count();
        let collider_count = colliders.len();
        let default_material = ColliderMaterial::new(params.friction, params.restitution);
        Ok(Self {
            articulation,
            spherical_orientations: None,
            positions: DVector::zeros(dof),
            velocities: DVector::zeros(dof),
            root_pose,
            floating,
            base_linear_velocity: Vector3::zeros(),
            base_angular_velocity: Vector3::zeros(),
            base_force: Vector3::zeros(),
            link_loads: vec![LinkExternalLoad::default(); link_count],
            colliders,
            ground_points: Vec::new(),
            boxes: Vec::new(),
            cylinders: Vec::new(),
            cones: Vec::new(),
            capsules: Vec::new(),
            convex_shapes: Vec::new(),
            scene_bodies: Vec::new(),
            contact_forces: vec![Vector3::zeros(); link_count],
            contact_torques: vec![Vector3::zeros(); link_count],
            contact_samples: vec![Vec::new(); link_count],
            joint_velocity_limit: None,
            self_contacts_enabled: true,
            implicit_coriolis: true,
            joint_motors: vec![None; dof],
            joint_passive: vec![JointPassive::default(); dof],
            joint_nonlinear_passive: vec![JointNonlinearPassive::default(); dof],
            joint_friction: vec![0.0; dof],
            joint_couplings: Vec::new(),
            joint_polynomial_couplings: Vec::new(),
            link_point_constraints: Vec::new(),
            link_fixed_constraints: Vec::new(),
            link_scene_point_constraints: Vec::new(),
            link_scene_fixed_constraints: Vec::new(),
            sphere_materials: vec![default_material; collider_count],
            ground_point_materials: Vec::new(),
            box_materials: Vec::new(),
            cylinder_materials: Vec::new(),
            cone_materials: Vec::new(),
            capsule_materials: Vec::new(),
            convex_materials: Vec::new(),
            scene_collider_materials: Vec::new(),
            ground_material: default_material,
            scene_sleep_states: Vec::new(),
            contact_cache: Vec::new(),
            params,
        })
    }

    /// Replace ground-only contact candidates after validating link references.
    pub fn set_ground_points(
        &mut self,
        points: Vec<LinkGroundPoint>,
    ) -> Result<(), ArticulatedWorldError> {
        if points.iter().any(|point| {
            point.link >= self.articulation.link_count()
                || point.local.iter().any(|value| !value.is_finite())
        }) {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        let default_material = self.default_material();
        self.ground_points = points;
        self.ground_point_materials = vec![default_material; self.ground_points.len()];
        self.clear_contact_cache();
        Ok(())
    }

    /// Replace oriented box collision shapes after validating their frames.
    pub fn set_boxes(&mut self, boxes: Vec<LinkBox>) -> Result<(), ArticulatedWorldError> {
        if boxes.iter().any(|shape| {
            shape.link >= self.articulation.link_count()
                || shape
                    .origin
                    .translation
                    .vector
                    .iter()
                    .any(|value| !value.is_finite())
                || shape
                    .origin
                    .rotation
                    .coords
                    .iter()
                    .any(|value| !value.is_finite())
                || shape
                    .half_extents
                    .iter()
                    .any(|value| !value.is_finite() || *value <= 0.0)
        }) {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        let default_material = self.default_material();
        self.boxes = boxes;
        self.box_materials = vec![default_material; self.boxes.len()];
        self.clear_contact_cache();
        Ok(())
    }

    /// Replace exact circular cylinders after validating their frames and dimensions.
    pub fn set_cylinders(
        &mut self,
        cylinders: Vec<LinkCylinder>,
    ) -> Result<(), ArticulatedWorldError> {
        if cylinders.iter().any(|shape| {
            shape.link >= self.articulation.link_count()
                || shape
                    .origin
                    .translation
                    .vector
                    .iter()
                    .any(|value| !value.is_finite())
                || shape
                    .origin
                    .rotation
                    .coords
                    .iter()
                    .any(|value| !value.is_finite())
                || !shape.half_height.is_finite()
                || shape.half_height <= 0.0
                || !shape.radius.is_finite()
                || shape.radius <= 0.0
        }) {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        let default_material = self.default_material();
        self.cylinders = cylinders;
        self.cylinder_materials = vec![default_material; self.cylinders.len()];
        self.clear_contact_cache();
        Ok(())
    }

