    /// Add an independent scene body and return its stable slot until removal.
    pub fn add_scene_body(&mut self, body: SceneBody) -> usize {
        let slot = self.scene_bodies.len();
        let default_material = self.default_material();
        self.scene_collider_materials
            .push(vec![default_material; body.colliders.len()]);
        self.scene_sleep_states.push(SleepState::default());
        self.scene_bodies.push(body);
        self.clear_contact_cache();
        slot
    }

    /// Remove a scene body. Later slots shift down by one.
    pub fn remove_scene_body(&mut self, slot: usize) -> bool {
        if slot >= self.scene_bodies.len() {
            return false;
        }
        let _removed = self.scene_bodies.remove(slot);
        self.link_scene_point_constraints.retain_mut(|constraint| {
            if constraint.body == slot {
                return false;
            }
            if constraint.body > slot {
                constraint.body -= 1;
            }
            true
        });
        self.link_scene_fixed_constraints.retain_mut(|constraint| {
            if constraint.body == slot {
                return false;
            }
            if constraint.body > slot {
                constraint.body -= 1;
            }
            true
        });
        if slot < self.scene_collider_materials.len() {
            let _removed = self.scene_collider_materials.remove(slot);
        }
        if slot < self.scene_sleep_states.len() {
            let _removed = self.scene_sleep_states.remove(slot);
        }
        self.clear_contact_cache();
        true
    }

    /// Teleport a scene body and discard cached impulses for its old location.
    pub fn set_scene_body_pose(
        &mut self,
        index: usize,
        pose: Isometry3<f64>,
    ) -> Result<(), ArticulatedWorldError> {
        if pose
            .translation
            .vector
            .iter()
            .any(|value| !value.is_finite())
            || pose.rotation.coords.iter().any(|value| !value.is_finite())
        {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        let body = self
            .scene_bodies
            .get_mut(index)
            .ok_or(ArticulatedWorldError::InvalidInput)?;
        body.pose = pose;
        let dynamic = body.mass > 0.0;
        if dynamic {
            self.wake_scene_body(index)?;
        }
        self.clear_contact_cache();
        Ok(())
    }

    /// Set prescribed motion on a zero-mass scene body; None restores static behavior.
    /// All inputs are validated before changing state. Forces and impulses do not
    /// change prescribed motion. Resident GPU composition supports spheres, boxes, capsules,
    /// cylinders, cones and convex hulls;
    /// other moving shapes and hot constraint-anchor pose edits require further support.
    pub fn set_scene_body_kinematic_motion(
        &mut self,
        index: usize,
        velocities: Option<(Vector3<f64>, Vector3<f64>)>,
    ) -> Result<(), ArticulatedWorldError> {
        let (linear, angular) = velocities.unwrap_or((Vector3::zeros(), Vector3::zeros()));
        if linear.iter().chain(angular.iter()).any(|v| !v.is_finite()) {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        let body = self
            .scene_bodies
            .get_mut(index)
            .filter(|body| body.mass == 0.0)
            .ok_or(ArticulatedWorldError::InvalidInput)?;
        body.kinematic = velocities.is_some();
        body.linear_velocity = linear;
        body.angular_velocity = angular;
        self.clear_contact_cache();
        Ok(())
    }

    /// Set a dynamic scene body's world-frame linear and angular velocities.
    pub fn set_scene_body_velocity(
        &mut self,
        index: usize,
        linear: Vector3<f64>,
        angular: Vector3<f64>,
    ) -> Result<(), ArticulatedWorldError> {
        if linear
            .iter()
            .chain(angular.iter())
            .any(|value| !value.is_finite())
        {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        let body = self
            .scene_bodies
            .get_mut(index)
            .filter(|body| body.mass > 0.0)
            .ok_or(ArticulatedWorldError::InvalidInput)?;
        body.linear_velocity = linear;
        body.angular_velocity = angular;
        self.wake_scene_body(index)?;
        Ok(())
    }

    /// Whether one dynamic scene body is currently sleeping.
    pub fn scene_body_is_sleeping(&self, index: usize) -> Option<bool> {
        let body = self.scene_bodies.get(index)?;
        Some(
            body.mass > 0.0
                && self
                    .scene_sleep_states
                    .get(index)
                    .is_some_and(|state| state.sleeping),
        )
    }

    /// Wake one dynamic scene body and reset its idle timer.
    pub fn wake_scene_body(&mut self, index: usize) -> Result<(), ArticulatedWorldError> {
        if self
            .scene_bodies
            .get(index)
            .is_none_or(|body| body.mass <= 0.0)
        {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        self.ensure_scene_sleep_states();
        self.scene_sleep_states[index].wake();
        Ok(())
    }

    /// Put one dynamic scene body to sleep and clear both velocities.
    pub fn sleep_scene_body(&mut self, index: usize) -> Result<(), ArticulatedWorldError> {
        if self
            .scene_bodies
            .get(index)
            .is_none_or(|body| body.mass <= 0.0)
        {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        self.ensure_scene_sleep_states();
        self.scene_sleep_states[index].sleep();
        self.scene_bodies[index].linear_velocity = Vector3::zeros();
        self.scene_bodies[index].angular_velocity = Vector3::zeros();
        Ok(())
    }

    /// Material assigned to a link sphere.
    pub fn link_sphere_material(&self, index: usize) -> Option<ColliderMaterial> {
        (index < self.colliders.len()).then(|| self.sphere_material(index))
    }

    /// Assign a contact material to a link sphere.
    pub fn set_link_sphere_material(
        &mut self,
        index: usize,
        material: ColliderMaterial,
    ) -> Result<(), ArticulatedWorldError> {
        let default_material = self.default_material();
        if !assign_material(
            &mut self.sphere_materials,
            self.colliders.len(),
            index,
            material,
            default_material,
        ) {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        self.clear_contact_cache();
        Ok(())
    }

    /// Material assigned to a ground contact point.
    pub fn ground_point_material(&self, index: usize) -> Option<ColliderMaterial> {
        (index < self.ground_points.len()).then(|| self.ground_point_material_at(index))
    }

    /// Assign a contact material to a ground contact point.
    pub fn set_ground_point_material(
        &mut self,
        index: usize,
        material: ColliderMaterial,
    ) -> Result<(), ArticulatedWorldError> {
        let default_material = self.default_material();
        if !assign_material(
            &mut self.ground_point_materials,
            self.ground_points.len(),
            index,
            material,
            default_material,
        ) {
            return Err(ArticulatedWorldError::InvalidInput);
        }
        self.clear_contact_cache();
        Ok(())
    }

