    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_kinematic_capsule_world_and_batch_transmit_contact_motion() {
        use crate::gpu_contact_pipeline::GpuContactDevice;
        use crate::gpu_scene_dynamics::{
            GpuSceneDynamics, GpuSceneDynamicsBatch, GpuSceneDynamicsError,
        };
        let build = |geometry: bool, velocity: f64| {
            let tree = Articulation::new(
                vec![
                    LinkSpec {
                        mass: 0.0,
                        center_of_mass: Vector3::zeros(),
                        inertia: Matrix3::zeros(),
                    },
                    LinkSpec {
                        mass: 1.0,
                        center_of_mass: Vector3::zeros(),
                        inertia: Matrix3::identity(),
                    },
                ],
                vec![JointSpec {
                    parent: 0,
                    child: 1,
                    origin: Isometry3::identity(),
                    kind: JointKind::Prismatic,
                    axis: Vector3::z(),
                    limits: None,
                }],
                0,
            )
            .unwrap();
            let mut world = ArticulatedWorld::new(
                tree,
                Isometry3::translation(0.0, 0.0, 0.5),
                if geometry {
                    vec![LinkSphere {
                        link: 1,
                        center: Vector3::zeros(),
                        radius: 0.5,
                    }]
                } else {
                    vec![]
                },
                ArticulatedWorldParams {
                    gravity: [0.0; 3],
                    ..Default::default()
                },
            )
            .unwrap();
            let mut body = SceneBody::new(
                Isometry3::translation(0.0, 0.0, -0.5),
                0.0,
                Matrix3::identity(),
                vec![SceneCollider::Capsule {
                    origin: Isometry3::from_parts(
                        Translation3::identity(),
                        UnitQuaternion::from_scaled_axis(
                            Vector3::y() * core::f64::consts::FRAC_PI_2,
                        ),
                    ),
                    half_height: 0.2,
                    radius: 0.5,
                }],
            )
            .unwrap();
            body.kinematic = true;
            body.linear_velocity.z = velocity;
            let _ = world.add_scene_body(body);
            let mut fixed = scene_sphere(4.0, 0.0);
            fixed.pose.translation.x = 10.0;
            let _ = world.add_scene_body(fixed);
            world
        };
        let context = GpuContactDevice::new().expect("GPU backend required");
        let mut world = build(true, 0.2);
        let mut session = GpuSceneDynamics::new(&world, &context, 0.001).unwrap();
        let _ = session.step(&mut world, &[0.0], 100).unwrap();
        assert!((world.velocities[0] - 0.2).abs() < 5e-4);
        assert!((world.scene_bodies[0].pose.translation.z + 0.48).abs() < 2e-6);
        world.scene_bodies[1].pose.translation.x += 1.0;
        session.update_static_scene_poses(&world).unwrap();
        let _ = session.step(&mut world, &[0.0], 10).unwrap();
        assert!((world.scene_bodies[0].pose.translation.z + 0.478).abs() < 2e-6);
        let previous = world.positions.clone();
        world.scene_bodies[0].linear_velocity.z = 0.3;
        assert!(matches!(
            session.step(&mut world, &[0.0], 1),
            Err(GpuSceneDynamicsError::WorldChanged)
        ));
        assert_eq!(world.positions, previous);
        world.scene_bodies[0].linear_velocity.z = 0.2;
        let _ = session.step(&mut world, &[0.0], 1).unwrap();

        let mut worlds = [build(true, 0.2), build(true, 0.0), build(false, 0.2)];
        let mut batch = GpuSceneDynamicsBatch::new(&worlds, &context, 0.001).unwrap();
        let _ = batch
            .step(&mut worlds, &[&[0.0], &[0.0], &[0.0]], 100)
            .unwrap();
        assert!((worlds[0].velocities[0] - 0.2).abs() < 5e-4);
        assert_eq!(worlds[1].velocities[0], 0.0);
        assert_eq!(worlds[2].velocities[0], 0.0);
        for (index, world) in worlds.iter().enumerate() {
            let expected = if index == 1 { -0.5 } else { -0.48 };
            assert!((world.scene_bodies[0].pose.translation.z - expected).abs() < 2e-6);
        }
        worlds[0].scene_bodies[1].pose.translation.x += 1.0;
        batch.update_static_scene_poses(&worlds).unwrap();
        let _ = batch
            .step(&mut worlds, &[&[0.0], &[0.0], &[0.0]], 10)
            .unwrap();
        assert!((worlds[0].scene_bodies[0].pose.translation.z + 0.478).abs() < 2e-6);
        assert_eq!(worlds[1].scene_bodies[0].pose.translation.z, -0.5);
        assert!((worlds[2].scene_bodies[0].pose.translation.z + 0.478).abs() < 2e-6);

        for (length, vertical, yaw, shift) in [
            (0.2, false, 0.0, 0.0),
            (2.0, false, 0.0, 0.0),
            (0.2, true, 0.0, 0.0),
            (2.0, false, core::f64::consts::FRAC_PI_4, 0.0),
            (0.2, false, 0.0, 0.7),
        ] {
            let mut convex_world = build(false, 0.2);
            convex_world.scene_bodies[0].pose.translation.x = shift;
            if let SceneCollider::Capsule {
                origin,
                half_height,
                ..
            } = &mut convex_world.scene_bodies[0].colliders[0]
            {
                *half_height = length;
                if vertical {
                    *origin = Isometry3::translation(0.0, 0.0, -0.2);
                }
            }
            let body = convex_world.add_scene_body(
                SceneBody::new(
                    Isometry3::from_parts(
                        Translation3::new(0.0, 0.0, 0.5),
                        UnitQuaternion::from_scaled_axis(Vector3::z() * yaw),
                    ),
                    1.0,
                    Matrix3::identity(),
                    vec![SceneCollider::Convex {
                        origin: Isometry3::identity(),
                        geometry: gpu_box_convex_geometry(Vector3::repeat(0.5)).unwrap(),
                    }],
                )
                .unwrap(),
            );
            let mut convex_session = GpuSceneDynamics::new(&convex_world, &context, 0.001).unwrap();
            let diagnostics = convex_session.step(&mut convex_world, &[0.0], 1).unwrap();
            let samples = &diagnostics.samples[body];
            assert_eq!(
                samples.len(),
                if vertical || shift > 0.0 { 1 } else { 2 },
                "length {length}, vertical {vertical}: {samples:?}"
            );
            if shift > 0.0 {
                assert!((samples[0].position.x - 0.5).abs() < 1e-5, "{samples:?}");
                assert!(convex_world.scene_bodies[body].angular_velocity.y < -1e-3);
                continue;
            }
            if !vertical {
                let extent = length.min(0.5 / yaw.cos().abs().max(yaw.sin().abs()));
                let mut xs: Vec<_> = samples.iter().map(|sample| sample.position.x).collect();
                xs.sort_by(f64::total_cmp);
                assert!((xs[0] + extent).abs() < 1e-5, "{xs:?}");
                assert!((xs[1] - extent).abs() < 1e-5, "{xs:?}");
            }
            let _ = convex_session.step(&mut convex_world, &[0.0], 99).unwrap();
            assert!(
                convex_world.scene_bodies[body].angular_velocity.norm() < 5e-4,
                "length {length}, vertical {vertical}: {:?}",
                convex_world.scene_bodies[body].angular_velocity
            );

            assert!((convex_world.scene_bodies[body].linear_velocity.z - 0.2).abs() < 5e-4);
            assert!((convex_world.scene_bodies[0].pose.translation.z + 0.48).abs() < 2e-6);
            convex_world.scene_bodies[1].pose.translation.x += 1.0;
            convex_session
                .update_static_scene_poses(&convex_world)
                .unwrap();
            let _ = convex_session.step(&mut convex_world, &[0.0], 10).unwrap();
            assert!((convex_world.scene_bodies[body].linear_velocity.z - 0.2).abs() < 5e-4);
            assert!((convex_world.scene_bodies[0].pose.translation.z + 0.478).abs() < 2e-6);
        }
    }

