    #[cfg(feature = "gpu-contact")]
    #[test]
    fn fixed_root_world_gpu_axial_shapes_contact_static_scene_sphere() {
        use crate::gpu_articulated_dynamics::GpuArticulatedDynamicsBatch;

        let build = |kind: GpuArticulatedGroundAxialKind,
                     direction: Vector3<f64>,
                     scene_distance: f64,
                     rotated: bool| {
            let articulation = Articulation::new(
                vec![
                    LinkSpec {
                        mass: 0.0,
                        center_of_mass: Vector3::zeros(),
                        inertia: Matrix3::zeros(),
                    },
                    LinkSpec {
                        mass: 1.0,
                        center_of_mass: Vector3::zeros(),
                        inertia: Matrix3::identity() * 0.1,
                    },
                ],
                vec![JointSpec {
                    parent: 0,
                    child: 1,
                    origin: Isometry3::identity(),
                    kind: JointKind::Prismatic,
                    axis: direction,
                    limits: None,
                }],
                0,
            )
            .unwrap();
            let mut world = ArticulatedWorld::new(
                articulation,
                Isometry3::translation(0.0, 0.0, 2.0),
                Vec::new(),
                ArticulatedWorldParams {
                    gravity: [0.0; 3],
                    ..Default::default()
                },
            )
            .unwrap();
            let shape_origin = if rotated {
                Isometry3::rotation(Vector3::y() * core::f64::consts::FRAC_PI_2)
            } else {
                Isometry3::identity()
            };
            match kind {
                GpuArticulatedGroundAxialKind::Cylinder => world
                    .set_cylinders(vec![LinkCylinder {
                        link: 1,
                        origin: shape_origin,
                        half_height: 0.5,
                        radius: 0.3,
                    }])
                    .unwrap(),
                GpuArticulatedGroundAxialKind::Cone => world
                    .set_cones(vec![LinkCone {
                        link: 1,
                        origin: shape_origin,
                        half_height: 0.5,
                        radius: 0.3,
                    }])
                    .unwrap(),
            }
            world.velocities[0] = 1.0;
            let center = Vector3::new(0.0, 0.0, 2.0) + direction * scene_distance;
            let _ = world.add_scene_body(
                SceneBody::new(
                    Isometry3::translation(center.x, center.y, center.z),
                    0.0,
                    Matrix3::zeros(),
                    vec![SceneCollider::Sphere {
                        center: Vector3::zeros(),
                        radius: 0.25,
                    }],
                )
                .unwrap(),
            );
            match kind {
                GpuArticulatedGroundAxialKind::Cylinder => world
                    .set_link_cylinder_material(0, ColliderMaterial::new(0.4, 0.1))
                    .unwrap(),
                GpuArticulatedGroundAxialKind::Cone => world
                    .set_link_cone_material(0, ColliderMaterial::new(0.4, 0.1))
                    .unwrap(),
            }
            world
                .set_scene_collider_material(0, 0, ColliderMaterial::new(0.2, 0.0))
                .unwrap();
            world
        };
        let cases = [
            (
                GpuArticulatedGroundAxialKind::Cylinder,
                Vector3::x(),
                0.5,
                false,
            ),
            (
                GpuArticulatedGroundAxialKind::Cylinder,
                Vector3::x(),
                0.1,
                false,
            ),
            (
                GpuArticulatedGroundAxialKind::Cylinder,
                Vector3::z(),
                0.7,
                false,
            ),
            (
                GpuArticulatedGroundAxialKind::Cone,
                Vector3::x(),
                0.35,
                false,
            ),
            (
                GpuArticulatedGroundAxialKind::Cone,
                Vector3::x(),
                0.1,
                false,
            ),
            (
                GpuArticulatedGroundAxialKind::Cone,
                -Vector3::z(),
                0.7,
                false,
            ),
            (
                GpuArticulatedGroundAxialKind::Cone,
                Vector3::z(),
                0.7,
                false,
            ),
            (
                GpuArticulatedGroundAxialKind::Cylinder,
                Vector3::x(),
                0.7,
                true,
            ),
            (GpuArticulatedGroundAxialKind::Cone, Vector3::x(), 0.7, true),
            (
                GpuArticulatedGroundAxialKind::Cylinder,
                Vector3::x(),
                3.0,
                false,
            ),
            (
                GpuArticulatedGroundAxialKind::Cone,
                Vector3::x(),
                3.0,
                false,
            ),
        ];
        let worlds = cases
            .iter()
            .map(|&(kind, direction, distance, rotated)| build(kind, direction, distance, rotated))
            .collect::<Vec<_>>();
        let inputs = worlds
            .iter()
            .map(|world| world.gpu_dynamics_input(&[0.0]).unwrap())
            .collect::<Vec<_>>();
        for (input, &(kind, _, _, _)) in inputs.iter().zip(&cases) {
            assert_eq!(input.static_axial_sphere_pairs.len(), 1);
            assert_eq!(input.static_axial_sphere_pairs[0].kind, kind);
            assert!((input.static_axial_sphere_pairs[0].friction - 0.3).abs() < 1e-12);
        }
        let mut with_static_box = build(
            GpuArticulatedGroundAxialKind::Cylinder,
            Vector3::x(),
            0.5,
            false,
        );
        with_static_box.scene_bodies[0].colliders[0] = SceneCollider::Box {
            origin: Isometry3::identity(),
            half_extents: Vector3::repeat(0.3),
        };
        assert_eq!(
            with_static_box
                .gpu_dynamics_input(&[0.0])
                .unwrap()
                .static_axial_box_pairs
                .len(),
            1
        );

        let mut tested = 0;
        for backend in [wgpu::Backends::VULKAN, wgpu::Backends::DX12] {
            let Ok(context) = GpuContactDevice::new_with_backends(backend) else {
                continue;
            };
            tested += 1;
            let batch = GpuArticulatedDynamicsBatch::new(&context, &inputs, 0.001).unwrap();
            batch.submit_steps(1).unwrap();
            let states = batch.readback().unwrap();
            for (index, &(kind, direction, distance, rotated)) in cases.iter().enumerate() {
                let mut cpu = build(kind, direction, distance, rotated);
                cpu.step(0.001, &[0.0]).unwrap();
                if distance < 2.0 {
                    assert!(states[index].velocities[0] < 1.0, "case {index}");
                } else {
                    assert!((states[index].velocities[0] - 1.0).abs() < 2e-4);
                }
                assert!(
                    (states[index].velocities[0] - cpu.velocities[0]).abs() < 2e-4,
                    "case {index}: GPU {}, CPU {}",
                    states[index].velocities[0],
                    cpu.velocities[0]
                );
            }
            let moved = GpuArticulatedDynamicsBatch::new(
                &context,
                core::slice::from_ref(&inputs[0]),
                0.001,
            )
            .unwrap();
            moved
                .set_root_pose(0, Isometry3::translation(-2.0, 0.0, 2.0))
                .unwrap();
            moved.submit_steps(1).unwrap();
            assert!((moved.readback().unwrap()[0].velocities[0] - 1.0).abs() < 2e-4);
        }
        assert!(tested > 0);
    }

