    #[cfg(feature = "gpu-contact")]
    #[test]
    fn fixed_root_world_uniform_spheres_use_gpu_pair_candidates() {
        use crate::gpu_articulated_dynamics::GpuArticulatedDynamicsBatch;
        use crate::gpu_articulated_ground_contact::self_contact_sphere_pairs;

        let articulation = Articulation::new(
            vec![
                LinkSpec {
                    mass: 0.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::zeros(),
                },
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::identity() * 0.1,
                },
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::identity() * 0.1,
                },
            ],
            vec![
                JointSpec {
                    parent: 0,
                    child: 1,
                    origin: Isometry3::identity(),
                    kind: JointKind::Prismatic,
                    axis: Vector3::x(),
                    limits: None,
                },
                JointSpec {
                    parent: 0,
                    child: 2,
                    origin: Isometry3::identity(),
                    kind: JointKind::Prismatic,
                    axis: Vector3::x(),
                    limits: None,
                },
            ],
            0,
        )
        .unwrap();
        let mut world = ArticulatedWorld::new(
            articulation,
            Isometry3::translation(0.0, 0.0, 2.0),
            vec![
                LinkSphere {
                    link: 1,
                    center: Vector3::new(-0.55, 0.0, 0.0),
                    radius: 0.5,
                },
                LinkSphere {
                    link: 2,
                    center: Vector3::new(0.55, 0.0, 0.0),
                    radius: 0.5,
                },
            ],
            ArticulatedWorldParams {
                gravity: [0.0; 3],
                ..Default::default()
            },
        )
        .unwrap();
        world.velocities[0] = 1.0;
        world.velocities[1] = -1.0;
        let input = world.gpu_dynamics_input(&[0.0, 0.0]).unwrap();
        assert_eq!(input.link_spheres.len(), 2);
        assert!(input.sphere_pairs.is_empty());
        let mut explicit = input.clone();
        explicit.sphere_pairs =
            self_contact_sphere_pairs(&world.articulation, &input.link_spheres).unwrap();
        explicit.link_spheres.clear();
        explicit.dynamic_material_rules.clear();
        let mut mixed_world = ArticulatedWorld::new(
            world.articulation.clone(),
            world.root_pose,
            world.colliders.clone(),
            world.params,
        )
        .unwrap();
        mixed_world.velocities.clone_from(&world.velocities);
        mixed_world
            .set_link_sphere_material(
                0,
                ColliderMaterial {
                    friction: 0.2,
                    restitution: 0.2,
                    friction_combine_rule: CoefficientCombineRule::Max,
                    restitution_combine_rule: CoefficientCombineRule::Min,
                },
            )
            .unwrap();
        mixed_world
            .set_link_sphere_material(1, ColliderMaterial::new(0.8, 0.8))
            .unwrap();
        let mixed = mixed_world.gpu_dynamics_input(&[0.0, 0.0]).unwrap();
        assert_eq!(mixed.link_spheres.len(), 2);
        assert!(mixed.sphere_pairs.is_empty());
        let mut mixed_explicit = mixed.clone();
        mixed_explicit.sphere_pairs =
            self_contact_sphere_pairs(&mixed_world.articulation, &mixed.link_spheres).unwrap();
        let combined = mixed_world
            .sphere_material(0)
            .combine(mixed_world.sphere_material(1));
        assert_eq!(combined.friction, 0.8);
        assert_eq!(combined.restitution, 0.2);
        mixed_explicit.sphere_pairs[0].friction = combined.friction;
        mixed_explicit.sphere_pairs[0].restitution = combined.restitution;
        mixed_explicit.link_spheres.clear();
        mixed_explicit.dynamic_material_rules.clear();
        let mut multiplied = mixed.clone();
        multiplied.dynamic_material_rules[0].friction = CoefficientCombineRule::Multiply;
        multiplied.dynamic_material_rules[1].friction = CoefficientCombineRule::Average;
        multiplied.dynamic_material_rules[0].restitution = CoefficientCombineRule::Average;
        multiplied.dynamic_material_rules[1].restitution = CoefficientCombineRule::Average;
        let mut tested = 0;
        for backend in [wgpu::Backends::VULKAN, wgpu::Backends::DX12] {
            let Ok(context) = GpuContactDevice::new_with_backends(backend) else {
                continue;
            };
            tested += 1;
            let batch =
                GpuArticulatedDynamicsBatch::new(&context, &[input.clone(), explicit.clone()], 0.1)
                    .unwrap();
            batch.submit_steps(1).unwrap();
            let result = batch.readback().unwrap();
            assert!(
                (&result[0].velocities - &result[1].velocities).norm() < 2e-4,
                "dynamic {:?}, explicit {:?}",
                result[0].velocities,
                result[1].velocities
            );
            assert!((result[0].velocities[0] - 1.0).abs() > 0.1);
            let mixed_batch = GpuArticulatedDynamicsBatch::new(
                &context,
                &[mixed.clone(), mixed_explicit.clone()],
                0.1,
            )
            .unwrap();
            mixed_batch.submit_steps(1).unwrap();
            let materials = mixed_batch.readback_dynamic_row_materials();
            assert!(
                materials
                    .iter()
                    .any(|row| { (row[0] - 0.2).abs() < 1e-5 && (row[2] - 0.8).abs() < 1e-5 }),
                "dynamic row materials {materials:?}"
            );
            let mixed_result = mixed_batch.readback().unwrap();
            assert!(
                (&mixed_result[0].velocities - &mixed_result[1].velocities).norm() < 2e-4,
                "dynamic {:?}, explicit {:?}",
                mixed_result[0].velocities,
                mixed_result[1].velocities
            );
            let multiplied_batch =
                GpuArticulatedDynamicsBatch::new(&context, &[multiplied.clone()], 0.1).unwrap();
            multiplied_batch.submit_steps(1).unwrap();
            let multiplied_materials = multiplied_batch.readback_dynamic_row_materials();
            assert!(
                multiplied_materials
                    .iter()
                    .any(|row| { (row[0] - 0.5).abs() < 1e-5 && (row[2] - 0.16).abs() < 1e-5 }),
                "dynamic row materials {multiplied_materials:?}"
            );
        }
        assert!(tested > 0);
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn fixed_root_world_gpu_sphere_pairs_follow_self_contact_filter() {
        let articulation = Articulation::new(
            vec![
                LinkSpec {
                    mass: 0.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::zeros(),
                },
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::identity(),
                },
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::identity(),
                },
            ],
            vec![
                JointSpec {
                    parent: 0,
                    child: 1,
                    origin: Isometry3::identity(),
                    kind: JointKind::Prismatic,
                    axis: Vector3::x(),
                    limits: None,
                },
                JointSpec {
                    parent: 0,
                    child: 2,
                    origin: Isometry3::identity(),
                    kind: JointKind::Prismatic,
                    axis: Vector3::y(),
                    limits: None,
                },
            ],
            0,
        )
        .unwrap();
        let mut world = ArticulatedWorld::new(
            articulation,
            Isometry3::translation(0.0, 0.0, 2.0),
            [0, 1, 2]
                .into_iter()
                .map(|link| LinkSphere {
                    link,
                    center: Vector3::zeros(),
                    radius: 0.2,
                })
                .collect(),
            ArticulatedWorldParams::default(),
        )
        .unwrap();
        world
            .set_link_sphere_material(1, ColliderMaterial::new(0.2, 0.0))
            .unwrap();
        world
            .set_link_sphere_material(
                2,
                ColliderMaterial {
                    friction: 0.8,
                    friction_combine_rule: CoefficientCombineRule::Max,
                    ..ColliderMaterial::default()
                },
            )
            .unwrap();
        world
            .set_capsules(vec![
                LinkCapsule {
                    link: 1,
                    origin: Isometry3::identity(),
                    half_height: 0.2,
                    radius: 0.1,
                },
                LinkCapsule {
                    link: 2,
                    origin: Isometry3::identity(),
                    half_height: 0.2,
                    radius: 0.1,
                },
            ])
            .unwrap();
        world
            .set_link_capsule_material(
                0,
                ColliderMaterial {
                    friction: 1.3,
                    friction_combine_rule: CoefficientCombineRule::Max,
                    ..ColliderMaterial::default()
                },
            )
            .unwrap();
        world
            .set_boxes(vec![
                LinkBox {
                    link: 1,
                    origin: Isometry3::identity(),
                    half_extents: Vector3::repeat(0.2),
                },
                LinkBox {
                    link: 2,
                    origin: Isometry3::identity(),
                    half_extents: Vector3::repeat(0.2),
                },
            ])
            .unwrap();
        world
            .set_link_box_material(
                0,
                ColliderMaterial {
                    friction: 1.7,
                    friction_combine_rule: CoefficientCombineRule::Max,
                    ..ColliderMaterial::default()
                },
            )
            .unwrap();
        let input = world.gpu_dynamics_input(&[0.0, 0.0]).unwrap();
        assert_eq!(input.link_spheres.len(), 3);
        assert_eq!(input.link_capsules.len(), 2);
        assert_eq!(input.link_boxes.len(), 2);
        assert_eq!(input.link_spheres[1].friction, 0.2);
        assert_eq!(input.link_capsules[0].friction, 1.3);
        assert_eq!(input.link_boxes[0].friction, 1.7);
        assert_eq!(input.dynamic_material_rules.len(), 7);
        assert_eq!(
            input.dynamic_material_rules[2].friction,
            CoefficientCombineRule::Max
        );
        assert!(input.sphere_pairs.is_empty());
        assert!(input.capsule_sphere_pairs.is_empty());
        assert!(input.capsule_pairs.is_empty());
        assert!(input.sphere_box_pairs.is_empty());
        assert!(input.capsule_box_pairs.is_empty());
        assert!(input.box_pairs.is_empty());
        let uniform = world.default_material();
        world.set_link_sphere_material(1, uniform).unwrap();
        world.set_link_sphere_material(2, uniform).unwrap();
        world.set_link_capsule_material(0, uniform).unwrap();
        world.set_link_box_material(0, uniform).unwrap();
        let dynamic = world.gpu_dynamics_input(&[0.0, 0.0]).unwrap();
        assert_eq!(dynamic.link_spheres.len(), 3);
        assert_eq!(dynamic.link_capsules.len(), 2);
        assert_eq!(dynamic.link_boxes.len(), 2);
        assert!(dynamic.sphere_pairs.is_empty());
        assert!(dynamic.capsule_sphere_pairs.is_empty());
        assert!(dynamic.capsule_pairs.is_empty());
        assert!(dynamic.sphere_box_pairs.is_empty());
        assert!(dynamic.capsule_box_pairs.is_empty());
        assert!(dynamic.box_pairs.is_empty());
        world
            .set_link_sphere_material(
                2,
                ColliderMaterial {
                    friction_combine_rule: CoefficientCombineRule::Multiply,
                    ..uniform
                },
            )
            .unwrap();
        let multiplied = world.gpu_dynamics_input(&[0.0, 0.0]).unwrap();
        assert_eq!(multiplied.link_spheres.len(), 3);
        assert_eq!(
            multiplied.dynamic_material_rules[2].friction,
            CoefficientCombineRule::Multiply
        );
        assert!(multiplied.sphere_pairs.is_empty());
        world.set_self_contacts_enabled(false);
        let disabled = world.gpu_dynamics_input(&[0.0, 0.0]).unwrap();
        assert!(disabled.sphere_pairs.is_empty());
        assert!(disabled.capsule_sphere_pairs.is_empty());
        assert!(disabled.capsule_pairs.is_empty());
        assert!(disabled.sphere_box_pairs.is_empty());
        assert!(disabled.capsule_box_pairs.is_empty());
        assert!(disabled.box_pairs.is_empty());
        world.params.solver_iterations = 65;
        assert!(matches!(
            world.gpu_dynamics_input(&[0.0, 0.0]),
            Err(ArticulatedWorldError::GpuResidentUnsupported(_))
        ));
        world.params.solver_iterations = 12;
        world
            .set_ground_material(ColliderMaterial {
                restitution: 1.5,
                restitution_combine_rule: CoefficientCombineRule::Max,
                ..ColliderMaterial::default()
            })
            .unwrap();
        assert!(matches!(
            world.gpu_dynamics_input(&[0.0, 0.0]),
            Err(ArticulatedWorldError::GpuResidentUnsupported(_))
        ));
    }

    fn spherical_pendulum() -> ArticulatedWorld {
        let tree = Articulation::new(
            vec![
                LinkSpec {
                    mass: 0.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::zeros(),
                },
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::new(1.0, 0.0, 0.0),
                    inertia: Matrix3::identity() * 0.1,
                },
            ],
            vec![JointSpec {
                parent: 0,
                child: 1,
                origin: Isometry3::identity(),
                kind: JointKind::Spherical,
                axis: Vector3::zeros(),
                limits: None,
            }],
            0,
        )
        .unwrap();
        ArticulatedWorld::new(
            tree,
            Isometry3::translation(0.0, 0.0, 0.2),
            vec![LinkSphere {
                link: 1,
                center: Vector3::new(1.0, 0.0, 0.0),
                radius: 0.2,
            }],
            ArticulatedWorldParams {
                max_substep: 0.001,
                ..Default::default()
            },
        )
        .unwrap()
    }

    #[test]
    fn implicit_coriolis_toggle_changes_midpoint_prediction_and_restores() {
        let mut explicit = spherical_pendulum();
        explicit.root_pose.translation.vector.z = 2.0;
        explicit.params.gravity = [0.0; 3];
        explicit.positions = DVector::from_vec(vec![0.2, -0.3, 0.4]);
        explicit.velocities = DVector::from_vec(vec![2.0, -1.0, 1.5]);
        let mut implicit = spherical_pendulum();
        implicit.root_pose = explicit.root_pose;
        implicit.params.gravity = explicit.params.gravity;
        implicit.positions = explicit.positions.clone();
        implicit.velocities = explicit.velocities.clone();
        assert!(explicit.implicit_coriolis());
        explicit.set_implicit_coriolis(false);
        let saved = explicit.snapshot();
        let explicit_step = explicit
            .prepare_contact_step(
                0.001,
                &[0.0; 3],
                #[cfg(feature = "gpu-contact")]
                None,
            )
            .unwrap();
        let initial = implicit
            .articulation
            .generalized_dynamics(
                implicit.root_pose,
                implicit.positions.as_slice(),
                &implicit.velocities,
                false,
                Vector3::zeros(),
            )
            .unwrap();
        let expected = &implicit.velocities
            + &explicit_step.problem.inverse_mass
                * (&explicit_step.applied_force - initial.velocity_bias)
                * 0.001;
        assert!((&explicit_step.predicted_velocity - &expected).norm() < 1e-10);
        let implicit_step = implicit
            .prepare_contact_step(
                0.001,
                &[0.0; 3],
                #[cfg(feature = "gpu-contact")]
                None,
            )
            .unwrap();
        assert!((&implicit_step.predicted_velocity - &expected).norm() > 1e-8);
        explicit.set_implicit_coriolis(true);
        explicit.restore_snapshot(&saved).unwrap();
        assert!(!explicit.implicit_coriolis());
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn gpu_device_mass_respects_explicit_coriolis_mode() {
        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let build = || {
            let mut world = spherical_pendulum();
            world.root_pose.translation.vector.z = 2.0;
            world.positions = DVector::from_vec(vec![0.2, -0.3, 0.4]);
            world.velocities = DVector::from_vec(vec![2.0, -1.0, 1.5]);
            world.set_implicit_coriolis(false);
            world
        };
        let mut cpu = build();
        let mut device_mass = build();
        cpu.step(0.001, &[0.0; 3]).unwrap();
        device_mass
            .step_gpu_device_mass(0.001, &[0.0; 3], &gpu)
            .unwrap();
        assert!((&device_mass.velocities - &cpu.velocities).norm() < 2e-5);
        assert!((&device_mass.positions - &cpu.positions).norm() < 2e-5);
    }

