    #[test]
    fn material_registry_tracks_shapes_and_scene_snapshots() {
        let mut world = floating_sphere();
        world
            .set_ground_points(vec![LinkGroundPoint {
                link: 0,
                local: Vector3::new(0.0, 0.0, -0.5),
            }])
            .unwrap();
        world
            .set_boxes(vec![LinkBox {
                link: 0,
                origin: Isometry3::identity(),
                half_extents: Vector3::repeat(0.25),
            }])
            .unwrap();
        world
            .set_cylinders(vec![LinkCylinder {
                link: 0,
                origin: Isometry3::identity(),
                half_height: 0.25,
                radius: 0.25,
            }])
            .unwrap();
        let sticky = ColliderMaterial {
            friction: 1.7,
            friction_combine_rule: CoefficientCombineRule::Max,
            ..ColliderMaterial::default()
        };
        world.set_ground_point_material(0, sticky).unwrap();
        world.set_link_box_material(0, sticky).unwrap();
        world.set_link_cylinder_material(0, sticky).unwrap();
        assert_eq!(world.ground_point_material(0), Some(sticky));
        assert_eq!(world.link_box_material(0), Some(sticky));
        assert_eq!(world.link_cylinder_material(0), Some(sticky));
        assert!(world.set_link_box_material(1, sticky).is_err());
        assert!(world.set_link_cylinder_material(1, sticky).is_err());

        let body = SceneBody::new(
            Isometry3::translation(0.0, 0.0, 2.0),
            1.0,
            Matrix3::identity(),
            vec![SceneCollider::Sphere {
                center: Vector3::zeros(),
                radius: 0.2,
            }],
        )
        .unwrap();
        let body_index = world.add_scene_body(body);
        world
            .set_scene_collider_material(body_index, 0, sticky)
            .unwrap();
        world.set_ground_material(sticky).unwrap();
        let snapshot = world.snapshot();
        world
            .set_link_box_material(0, ColliderMaterial::default())
            .unwrap();
        world
            .set_link_cylinder_material(0, ColliderMaterial::default())
            .unwrap();
        world
            .set_scene_collider_material(body_index, 0, ColliderMaterial::default())
            .unwrap();
        world
            .set_ground_material(ColliderMaterial::default())
            .unwrap();
        world.restore_snapshot(&snapshot).unwrap();
        assert_eq!(world.link_box_material(0), Some(sticky));
        assert_eq!(world.link_cylinder_material(0), Some(sticky));
        assert_eq!(world.scene_collider_material(body_index, 0), Some(sticky));
        assert_eq!(world.ground_material(), sticky);
    }

    #[test]
    fn link_cylinder_validation_rejects_invalid_geometry() {
        let mut world = floating_sphere();
        let valid = LinkCylinder {
            link: 0,
            origin: Isometry3::identity(),
            half_height: 0.5,
            radius: 0.25,
        };
        world.set_cylinders(vec![valid.clone()]).unwrap();

        let mut invalid = valid.clone();
        invalid.link = 1;
        assert!(world.set_cylinders(vec![invalid]).is_err());
        let mut invalid = valid.clone();
        invalid.radius = 0.0;
        assert!(world.set_cylinders(vec![invalid]).is_err());
        let mut invalid = valid;
        invalid.half_height = f64::NAN;
        assert!(world.set_cylinders(vec![invalid]).is_err());
    }

