    #[cfg(feature = "gpu-contact")]
    #[test]
    fn link_capsule_ground_and_scene_sphere_match_cpu_gpu() {
        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let mut reference = floating_capsule();
        let mut actual = floating_capsule();
        for world in [&mut reference, &mut actual] {
            world.root_pose.translation.vector.z = 0.64;
        }
        reference.step(0.001, &[]).unwrap();
        actual.step_gpu(0.001, &[], &gpu).unwrap();
        assert!(reference.contact_forces[0].z > 9.0);
        assert!((actual.contact_forces[0] - reference.contact_forces[0]).norm() < 1e-3);
        assert!(
            (actual.root_pose.translation.vector - reference.root_pose.translation.vector).norm()
                < 1e-5
        );

        let mut reference = floating_capsule();
        let mut actual = floating_capsule();
        for world in [&mut reference, &mut actual] {
            world.root_pose.translation.vector = Vector3::new(0.0, 0.0, 2.0);
            world.base_linear_velocity = Vector3::zeros();
            world.params.gravity = [0.0; 3];
            let _body = world.add_scene_body(
                SceneBody::new(
                    Isometry3::translation(0.45, 0.0, 2.0),
                    0.0,
                    Matrix3::identity(),
                    vec![SceneCollider::Sphere {
                        center: Vector3::zeros(),
                        radius: 0.25,
                    }],
                )
                .unwrap(),
            );
        }
        reference.step(0.001, &[]).unwrap();
        actual.step_gpu(0.001, &[], &gpu).unwrap();
        assert!(
            reference.contact_forces[0].x < 0.0,
            "{:?}",
            reference.contact_forces[0]
        );
        assert!((actual.contact_forces[0] - reference.contact_forces[0]).norm() < 1e-2);
    }

