    #[cfg(feature = "gpu-contact")]
    #[test]
    fn gpu_link_cylinder_ground_matches_cpu() {
        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let mut reference = floating_cylinder();
        let mut actual = floating_cylinder();
        reference.step(0.02, &[]).unwrap();
        actual.step_gpu(0.02, &[], &gpu).unwrap();

        assert!(
            (actual.root_pose.translation.vector - reference.root_pose.translation.vector).norm()
                < 1e-6
        );
        // Redundant rim contacts can distribute small lateral f32 impulses differently.
        assert!(
            (actual.contact_forces[0].z - reference.contact_forces[0].z).abs() < 1e-3,
            "actual={:?} reference={:?}",
            actual.contact_forces[0],
            reference.contact_forces[0]
        );
        assert!(actual.contact_forces[0].xy().norm() < 0.1);
    }

