    #[test]
    fn torque_free_asymmetric_floating_body_preserves_energy() {
        let inertia = Matrix3::from_diagonal(&Vector3::new(0.1, 0.2, 0.3));
        let tree = Articulation::new(
            vec![LinkSpec {
                mass: 1.0,
                center_of_mass: Vector3::zeros(),
                inertia,
            }],
            vec![],
            0,
        )
        .unwrap();
        let mut world = ArticulatedWorld::new_floating(
            tree,
            Isometry3::translation(0.0, 0.0, 100.0),
            vec![],
            ArticulatedWorldParams {
                gravity: [0.0; 3],
                max_substep: 0.01,
                ..ArticulatedWorldParams::default()
            },
        )
        .unwrap();
        world.base_angular_velocity = Vector3::new(10.0, 20.0, 15.0);
        let energy = |world: &ArticulatedWorld| {
            let rotation = world.root_pose.rotation.to_rotation_matrix();
            let world_inertia = rotation.matrix() * inertia * rotation.matrix().transpose();
            0.5 * world
                .base_angular_velocity
                .dot(&(world_inertia * world.base_angular_velocity))
        };
        let initial = energy(&world);
        for _ in 0..1000 {
            world.step(0.01, &[]).unwrap();
        }
        let ratio = energy(&world) / initial;
        assert!((ratio - 1.0).abs() < 0.05, "energy ratio {ratio}");
    }

    #[test]
    fn torque_free_floating_joint_preserves_energy() {
        let tree = Articulation::new(
            vec![
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::identity() * 0.1,
                },
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::new(0.5, 0.0, 0.0),
                    inertia: Matrix3::identity() * 0.05,
                },
            ],
            vec![JointSpec {
                parent: 0,
                child: 1,
                origin: Isometry3::translation(0.0, 0.0, 0.5),
                kind: JointKind::Revolute,
                axis: Vector3::y(),
                limits: None,
            }],
            0,
        )
        .unwrap();
        let mut world = ArticulatedWorld::new_floating(
            tree,
            Isometry3::translation(0.0, 0.0, 100.0),
            vec![],
            ArticulatedWorldParams {
                gravity: [0.0; 3],
                max_substep: 0.01,
                ..ArticulatedWorldParams::default()
            },
        )
        .unwrap();
        world.base_angular_velocity = Vector3::new(3.0, 5.0, 2.0);
        world.velocities[0] = 4.0;
        let energy = |world: &ArticulatedWorld| {
            let velocity = DVector::from_vec(vec![
                world.base_linear_velocity.x,
                world.base_linear_velocity.y,
                world.base_linear_velocity.z,
                world.base_angular_velocity.x,
                world.base_angular_velocity.y,
                world.base_angular_velocity.z,
                world.velocities[0],
            ]);
            let dynamics = world
                .articulation
                .generalized_dynamics(
                    world.root_pose,
                    world.positions.as_slice(),
                    &velocity,
                    true,
                    Vector3::zeros(),
                )
                .unwrap();
            0.5 * velocity.dot(&(&dynamics.mass * &velocity))
        };
        let initial = energy(&world);
        for _ in 0..1000 {
            world.step(0.01, &[0.0]).unwrap();
        }
        let ratio = energy(&world) / initial;
        assert!((ratio - 1.0).abs() < 0.05, "energy ratio {ratio}");
    }

    #[test]
    fn floating_joint_limits_preserve_center_of_mass() {
        let tree = Articulation::new(
            vec![
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::identity() * 0.1,
                },
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::new(0.5, 0.0, 0.0),
                    inertia: Matrix3::identity() * 0.1,
                },
            ],
            vec![JointSpec {
                parent: 0,
                child: 1,
                origin: Isometry3::translation(0.0, 0.0, 0.5),
                kind: JointKind::Revolute,
                axis: Vector3::y(),
                limits: Some((-0.2, 0.2)),
            }],
            0,
        )
        .unwrap();
        let mut world = ArticulatedWorld::new_floating(
            tree,
            Isometry3::translation(0.0, 0.0, 100.0),
            vec![],
            ArticulatedWorldParams {
                gravity: [0.0; 3],
                max_substep: 0.01,
                ..ArticulatedWorldParams::default()
            },
        )
        .unwrap();
        world.joint_velocity_limit = Some(1.0);
        let center_of_mass = |world: &ArticulatedWorld| {
            let links = world.link_poses().unwrap();
            (links[0].translation.vector
                + links[1].transform_point(&Point3::new(0.5, 0.0, 0.0)).coords)
                * 0.5
        };
        let initial = center_of_mass(&world);
        for _ in 0..100 {
            world.step(0.01, &[10.0]).unwrap();
        }
        let drift = (center_of_mass(&world) - initial).norm();
        assert!(drift < 0.1, "free center of mass drifted {drift} m");
        assert!(world.velocities[0].abs() <= 1.0);
        assert!(world.positions[0].abs() <= 0.2);
    }

    #[test]
    fn many_limited_joints_do_not_translate_free_center_of_mass() {
        let mut links = vec![LinkSpec {
            mass: 8.0,
            center_of_mass: Vector3::zeros(),
            inertia: Matrix3::identity() * 0.2,
        }];
        let mut joints = Vec::new();
        for index in 0..12 {
            links.push(LinkSpec {
                mass: 0.5,
                center_of_mass: Vector3::new(0.2, 0.0, 0.0),
                inertia: Matrix3::identity() * 0.0005,
            });
            joints.push(JointSpec {
                parent: 0,
                child: index + 1,
                origin: Isometry3::translation(
                    if index % 2 == 0 { -0.1 } else { 0.1 },
                    index as f64 * 0.02,
                    0.0,
                ),
                kind: JointKind::Revolute,
                axis: Vector3::y(),
                limits: Some((-0.5, 0.5)),
            });
        }
        let tree = Articulation::new(links, joints, 0).unwrap();
        let mut world = ArticulatedWorld::new_floating(
            tree,
            Isometry3::translation(0.0, 0.0, 100.0),
            vec![],
            ArticulatedWorldParams {
                gravity: [0.0; 3],
                max_substep: 0.001,
                ..ArticulatedWorldParams::default()
            },
        )
        .unwrap();
        world.joint_velocity_limit = Some(3.979);
        let center_of_mass = |world: &ArticulatedWorld| {
            let poses = world.link_poses().unwrap();
            let mut weighted = poses[0].translation.vector * 8.0;
            for pose in poses.iter().skip(1) {
                weighted += pose.transform_point(&Point3::new(0.2, 0.0, 0.0)).coords * 0.5;
            }
            weighted / 14.0
        };
        let initial = center_of_mass(&world);
        for step in 0..1000 {
            let torques = (0..12)
                .map(|index| {
                    if (index + step / 10) % 2 == 0 {
                        16.0
                    } else {
                        -16.0
                    }
                })
                .collect::<Vec<_>>();
            world.step(0.01, &torques).unwrap();
        }
        let drift = (center_of_mass(&world) - initial).norm();
        assert!(drift < 0.1, "free center of mass drifted {drift} m");
    }

