    #[test]
    fn solid_scene_cone_preserves_shape_pose_and_centroid_inertia() {
        let shape_pose = Isometry3::from_parts(
            Translation3::new(4.0, -2.0, 3.0),
            UnitQuaternion::from_axis_angle(&Vector3::y_axis(), 0.7),
        );
        for mass in [0.0, 10.0] {
            let body = SceneBody::solid_cone(shape_pose, 2.0, 2.0, mass).unwrap();
            let SceneCollider::Cone { origin, .. } = &body.colliders[0] else {
                panic!("expected cone");
            };
            assert!(
                (body.pose.translation.vector
                    - shape_pose
                        .transform_point(&Point3::new(0.0, 0.0, -1.0))
                        .coords)
                    .norm()
                    < 1e-12
            );
            assert!(
                ((body.pose * origin).to_homogeneous() - shape_pose.to_homogeneous()).norm()
                    < 1e-12
            );
            assert_eq!(body.inertia, Matrix3::identity() * (1.2 * mass));
            assert_eq!(body.linear_velocity, Vector3::zeros());
            assert_eq!(body.angular_velocity, Vector3::zeros());
        }
        assert!(SceneBody::solid_cone(shape_pose, -1.0, 2.0, 10.0).is_err());
        assert!(
            SceneBody::solid_cone(Isometry3::translation(f64::NAN, 0.0, 0.0), 2.0, 2.0, 10.0)
                .is_err()
        );
    }

    fn scene_cone(position: Vector3<f64>, mass: f64) -> SceneBody {
        SceneBody::new(
            Isometry3::translation(position.x, position.y, position.z),
            mass,
            Matrix3::identity() * 0.1,
            vec![SceneCollider::Cone {
                origin: Isometry3::identity(),
                half_height: 0.5,
                radius: 0.5,
            }],
        )
        .unwrap()
    }

    fn scene_polyline(z: f64) -> SceneBody {
        let geometry = PolylineGeometry::new(
            vec![Vector3::new(-1.0, 0.0, 0.0), Vector3::new(1.0, 0.0, 0.0)],
            vec![[0, 1]],
        )
        .unwrap();
        SceneBody::new(
            Isometry3::translation(0.0, 0.0, z),
            0.0,
            Matrix3::identity(),
            vec![SceneCollider::Polyline {
                origin: Isometry3::identity(),
                geometry,
            }],
        )
        .unwrap()
    }

    fn flat_trimesh(z: f64) -> SceneBody {
        let geometry = TriangleMeshGeometry::new(
            vec![
                Vector3::new(-2.0, -2.0, 0.0),
                Vector3::new(2.0, -2.0, 0.0),
                Vector3::new(2.0, 2.0, 0.0),
                Vector3::new(-2.0, 2.0, 0.0),
            ],
            vec![[0, 1, 2], [0, 2, 3]],
        )
        .unwrap();
        SceneBody::new(
            Isometry3::translation(0.0, 0.0, z),
            0.0,
            Matrix3::identity(),
            vec![SceneCollider::TriangleMesh {
                origin: Isometry3::identity(),
                geometry,
            }],
        )
        .unwrap()
    }

    fn flat_heightfield(z: f64, rows: usize, columns: usize) -> SceneBody {
        let geometry = HeightFieldGeometry::new(
            rows,
            columns,
            vec![0.0; rows * columns],
            Vector3::new(4.0, 4.0, 1.0),
        )
        .unwrap();
        SceneBody::new(
            Isometry3::translation(0.0, 0.0, z),
            0.0,
            Matrix3::identity(),
            vec![SceneCollider::HeightField {
                origin: Isometry3::identity(),
                geometry,
            }],
        )
        .unwrap()
    }

    #[test]
    fn cpu_scene_kinematic_integrates_prescribed_motion_and_stops_transactionally() {
        let mut world = floating_sphere();
        world.colliders.clear();
        world.params.max_substep = 0.1;
        world.params.gravity = [0.0, 0.0, -10.0];
        let moving = world.add_scene_body(scene_sphere(3.0, 0.0));
        let mut stationary = scene_sphere(3.0, 0.0);
        stationary.pose.translation.vector.x = 10.0;
        stationary.linear_velocity.x = 3.0;
        let fixed = world.add_scene_body(stationary);
        let mut dynamic = scene_sphere(3.0, 1.0);
        dynamic.pose.translation.vector.x = 20.0;
        let dynamic = world.add_scene_body(dynamic);
        assert!(
            world
                .set_scene_body_kinematic_motion(
                    moving,
                    Some((Vector3::repeat(f64::NAN), Vector3::zeros()))
                )
                .is_err()
        );
        assert!(!world.scene_bodies[moving].kinematic);
        assert!(
            world
                .set_scene_body_kinematic_motion(dynamic, Some((Vector3::x(), Vector3::zeros())))
                .is_err()
        );
        world
            .set_scene_body_kinematic_motion(
                moving,
                Some((Vector3::new(1.0, 2.0, 0.0), Vector3::z())),
            )
            .unwrap();
        world.scene_bodies[moving].force = Vector3::repeat(100.0);
        world.step(0.1, &[]).unwrap();
        world.step(0.1, &[]).unwrap();
        let body = &world.scene_bodies[moving];
        assert!((body.pose.translation.vector - Vector3::new(0.2, 0.4, 3.0)).norm() < 1e-10);
        assert!((body.pose.rotation.scaled_axis() - Vector3::z() * 0.2).norm() < 1e-10);
        assert_eq!(body.linear_velocity, Vector3::new(1.0, 2.0, 0.0));
        assert_eq!(body.angular_velocity, Vector3::z());
        assert_eq!(
            world.scene_bodies[fixed].pose.translation.vector,
            Vector3::new(10.0, 0.0, 3.0)
        );
        #[cfg(feature = "gpu-contact")]
        assert!(world.compose_scene_dynamics().is_ok());
        let pose = world.scene_bodies[moving].pose;
        let snapshot = world.snapshot();
        world.set_scene_body_kinematic_motion(moving, None).unwrap();
        world.step(0.1, &[]).unwrap();
        assert_eq!(world.scene_bodies[moving].pose, pose);
        assert_eq!(world.scene_bodies[moving].linear_velocity, Vector3::zeros());
        assert!(!world.scene_bodies[moving].kinematic);
        world.restore_snapshot(&snapshot).unwrap();
        assert!(world.scene_bodies[moving].kinematic);
        world.step(0.1, &[]).unwrap();
        assert!((world.scene_bodies[moving].pose.translation.vector.x - 0.3).abs() < 1e-10);
        let mut invalid = snapshot;
        invalid.scene_bodies[moving].mass = 1.0;
        let pose = world.scene_bodies[moving].pose;
        assert!(world.restore_snapshot(&invalid).is_err());
        assert_eq!(world.scene_bodies[moving].pose, pose);
    }

    #[test]
    fn cpu_scene_kinematic_pushes_sleeping_sphere_without_impulse_feedback() {
        let mut world = floating_sphere();
        world.colliders.clear();
        world.params.gravity = [0.0; 3];
        world.params.max_substep = 0.01;
        world.params.friction = 0.0;
        world.params.sleep.time_threshold = 0.015;
        let moving = world.add_scene_body(scene_sphere(3.0, 0.0));
        let mut dynamic = scene_sphere(3.0, 1.0);
        dynamic.pose.translation.vector.x = 0.999999;
        let dynamic = world.add_scene_body(dynamic);
        world.sleep_scene_body(dynamic).unwrap();
        world
            .set_scene_body_kinematic_motion(moving, Some((Vector3::x() * 0.005, Vector3::zeros())))
            .unwrap();
        for frame in 0..10 {
            world.step(0.01, &[]).unwrap();
            assert_eq!(
                world.scene_body_is_sleeping(dynamic),
                Some(false),
                "frame {frame}"
            );
            assert!(
                world.scene_bodies[dynamic].linear_velocity.x > 0.0049,
                "frame {frame}: {:?}",
                world.scene_bodies
            );
            assert_eq!(
                world.scene_bodies[moving].linear_velocity,
                Vector3::x() * 0.005
            );
            assert!(
                (world.scene_bodies[moving].pose.translation.vector.x
                    - (frame + 1) as f64 * 0.00005)
                    .abs()
                    < 1e-10
            );
        }
    }

