        let moving = world.add_scene_body(moving);
        let mut carried = scene_sphere(0.5, 1.0);
        carried.pose.translation.vector.x = 10.0;
        let carried = world.add_scene_body(carried);
        let mut unrelated = scene_sphere(0.5, 1.0);
        unrelated.pose.translation.vector.x = 20.0;
