    #[cfg(feature = "gpu-contact")]
    #[test]
    fn gpu_scene_capsules_match_cpu() {
        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let build_world = || {
            let mut world = floating_sphere();
            world.colliders.clear();
            let _fixed = world.add_scene_body(scene_capsule(2.0, 0.0));
            let moving = world.add_scene_body(scene_capsule(2.0, 1.0));
            world.scene_bodies[moving].pose.translation.vector.x = 0.4;
            world
        };
        let mut reference = build_world();
        let mut actual = build_world();

        let cpu_contact = reference.prepare_contact_step(0.001, &[], None).unwrap();
        let gpu_contact = actual.prepare_contact_step(0.001, &[], Some(&gpu)).unwrap();
        assert_eq!(cpu_contact.contact_frames.len(), 1);
        assert_eq!(gpu_contact.contact_frames.len(), 1);
        let expected = cpu_contact.contact_frames[0];
        let result = gpu_contact.contact_frames[0];
        assert!((result.position - expected.position).norm() < 1e-5);
        assert!((result.normal - expected.normal).norm() < 1e-5);
        assert!((result.depth - expected.depth).abs() < 1e-5);

        reference.step(0.001, &[]).unwrap();
        actual.step_gpu(0.001, &[], &gpu).unwrap();

        assert!(
            (actual.scene_bodies[1].linear_velocity - reference.scene_bodies[1].linear_velocity)
                .norm()
                < 1e-5
        );
        assert!(actual.scene_bodies[1].linear_velocity.x > 0.0);
    }

