    #[cfg(feature = "gpu-contact")]
    #[test]
    fn gpu_analytic_shapes_and_polyline_match_cpu() {
        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let build_world = || {
            let mut world = floating_sphere();
            world.colliders.clear();
            let _cylinder = world.add_scene_body(scene_cylinder(Vector3::new(0.0, 0.0, 2.0), 0.0));
            let cylinder_sphere = world.add_scene_body(scene_sphere(2.0, 1.0));
            world.scene_bodies[cylinder_sphere]
                .pose
                .translation
                .vector
                .x = 0.8;
            let _cone = world.add_scene_body(scene_cone(Vector3::new(5.0, 0.0, 2.0), 0.0));
            let cone_sphere = world.add_scene_body(scene_sphere(2.8, 1.0));
            world.scene_bodies[cone_sphere].pose.translation.vector.x = 5.0;
            let line = world.add_scene_body(scene_polyline(2.0));
            world.scene_bodies[line].pose.translation.vector.x = 10.0;
            let line_sphere = world.add_scene_body(scene_sphere(2.0, 1.0));
            world.scene_bodies[line_sphere].pose.translation.vector.x = 10.0;
            world.scene_bodies[line_sphere].pose.translation.vector.y = 0.3;
            world
        };
        let mut reference = build_world();
        let mut actual = build_world();
        let cpu_contacts = reference.prepare_contact_step(0.001, &[], None).unwrap();
        let gpu_contacts = actual.prepare_contact_step(0.001, &[], Some(&gpu)).unwrap();
        assert_eq!(cpu_contacts.contact_frames.len(), 3);
        assert_eq!(gpu_contacts.contact_frames.len(), 3);
        for (expected, result) in cpu_contacts
            .contact_frames
            .iter()
            .zip(&gpu_contacts.contact_frames)
        {
            assert!((expected.position - result.position).norm() < 1e-5);
            assert!((expected.normal - result.normal).norm() < 1e-5);
            assert!((expected.depth - result.depth).abs() < 1e-5);
        }
        reference.step(0.001, &[]).unwrap();
        actual.step_gpu(0.001, &[], &gpu).unwrap();

        for index in [1, 3, 5] {
            assert!(
                (actual.scene_bodies[index].linear_velocity
                    - reference.scene_bodies[index].linear_velocity)
                    .norm()
                    < 1e-4,
                "scene body {index} diverged"
            );
        }
    }

