    #[test]
    fn mesh_seam_reduces_duplicate_sphere_contacts() {
        let mut world = floating_sphere();
        world.colliders.clear();
        let _terrain = world.add_scene_body(flat_trimesh(1.0));
        let _moving = world.add_scene_body(scene_sphere(1.5, 1.0));
        #[cfg(feature = "gpu-contact")]
        let pending = world.prepare_contact_step(0.001, &[], None).unwrap();
        #[cfg(not(feature = "gpu-contact"))]
        let pending = world.prepare_contact_step(0.001, &[]).unwrap();
        assert_eq!(
            pending.contact_frames.len(),
            1,
            "{:?}",
            pending
                .contact_frames
                .iter()
                .map(|frame| (frame.position, frame.normal, frame.depth))
                .collect::<Vec<_>>()
        );
        let contact = pending.contact_frames[0];
        assert!(contact.position.x.abs() < 1e-9);
        assert!(contact.position.y.abs() < 1e-9);
        assert!((contact.normal - Vector3::z()).norm() < 1e-9);
        assert!((contact.depth - TRIANGLE_HALF_THICKNESS).abs() < 1e-9);
    }

    #[test]
    fn tilted_mesh_sphere_contact_uses_projected_surface_point() {
        let [a, b, c] = [
            Vector3::new(-1.0, -1.0, 0.0),
            Vector3::new(1.0, -1.0, 0.0),
            Vector3::new(0.0, 1.0, 1.0),
        ];
        let normal = (b - a).cross(&(c - a)).normalize();
        let surface = (a + b + c) / 3.0;
        let center = surface + normal * 0.5;
        let terrain = SceneBody::new(
            Isometry3::identity(),
            0.0,
            Matrix3::identity(),
            vec![SceneCollider::TriangleMesh {
                origin: Isometry3::identity(),
                geometry: TriangleMeshGeometry::new(vec![a, b, c], vec![[0, 1, 2]]).unwrap(),
            }],
        )
        .unwrap();
        let sphere = SceneBody::new(
            Isometry3::translation(center.x, center.y, center.z),
            1.0,
            Matrix3::identity() * 0.1,
            vec![SceneCollider::Sphere {
                center: Vector3::zeros(),
                radius: 0.5,
            }],
        )
        .unwrap();
        let mut world = floating_sphere();
        world.colliders.clear();
        let _terrain = world.add_scene_body(terrain);
        let _sphere = world.add_scene_body(sphere);
        #[cfg(feature = "gpu-contact")]
        let pending = world.prepare_contact_step(0.001, &[], None).unwrap();
        #[cfg(not(feature = "gpu-contact"))]
        let pending = world.prepare_contact_step(0.001, &[]).unwrap();
        assert_eq!(pending.contact_frames.len(), 1);
        let contact = pending.contact_frames[0];
        assert!((contact.normal - normal).norm() < 1e-9);
        assert!(
            (contact.position - surface - normal * TRIANGLE_HALF_THICKNESS * 0.5).norm() < 1e-9
        );
        assert!((contact.depth - TRIANGLE_HALF_THICKNESS).abs() < 1e-9);
        #[cfg(feature = "gpu-contact")]
        if let Ok(gpu) = GpuContactDevice::new() {
            let gpu_pending = world.prepare_contact_step(0.001, &[], Some(&gpu)).unwrap();
            assert_eq!(gpu_pending.contact_frames.len(), 1);
            assert!((gpu_pending.contact_frames[0].position - contact.position).norm() < 1e-6);
            assert!((gpu_pending.contact_frames[0].normal - contact.normal).norm() < 1e-6);
        }
    }

