    #[test]
    fn persistent_impulses_support_a_box_with_one_solver_iteration() {
        let mut warm = scene_box_box_contact();
        let mut cold = scene_box_box_contact();
        warm.params.solver_iterations = 1;
        cold.params.solver_iterations = 1;
        for _ in 0..500 {
            warm.step(0.001, &[]).unwrap();
            cold.clear_contact_cache();
            cold.step(0.001, &[]).unwrap();
        }
        let target_height = 2.1;
        let warm_error = (warm.scene_bodies[1].pose.translation.vector.z - target_height).abs();
        let cold_error = (cold.scene_bodies[1].pose.translation.vector.z - target_height).abs();
        assert!(warm_error < 0.1);
        assert!(
            warm_error <= cold_error + 0.01,
            "warm={warm_error}, cold={cold_error}"
        );
    }

