    #[test]
    fn joint_armature_reduces_applied_torque_acceleration() {
        let mut bare = pendulum();
        let mut with_armature = pendulum();
        bare.params.gravity = [0.0; 3];
        with_armature.params.gravity = [0.0; 3];
        with_armature
            .articulation
            .set_joint_armature(0, &[2.0])
            .unwrap();
        let pose = bare
            .articulation
            .pose(bare.root_pose, bare.positions.as_slice())
            .unwrap();
        let bare_inertia = bare
            .articulation
            .dynamics(&pose, Vector3::zeros())
            .unwrap()
            .mass[(0, 0)];
        bare.step(0.001, &[1.0]).unwrap();
        with_armature.step(0.001, &[1.0]).unwrap();
        assert!((bare.velocities[0] - 0.001 / bare_inertia).abs() < 1e-8);
        assert!((with_armature.velocities[0] - 0.001 / (bare_inertia + 2.0)).abs() < 1e-8);

        #[cfg(feature = "gpu-contact")]
        if let Ok(gpu) = GpuContactDevice::new() {
            let mut gpu_world = pendulum();
            gpu_world.params.gravity = [0.0; 3];
            gpu_world
                .articulation
                .set_joint_armature(0, &[2.0])
                .unwrap();
            gpu_world.step_gpu(0.001, &[1.0], &gpu).unwrap();
            assert!((gpu_world.velocities[0] - with_armature.velocities[0]).abs() < 1e-8);
        }
    }

    #[test]
    fn link_loads_match_generalized_gravity_and_torque_and_restore() {
        let mut gravity = pendulum();
        let mut force = pendulum();
        force.set_link_gravity_scale(1, 0.0).unwrap();
        force
            .set_link_external_wrench(1, Vector3::new(0.0, 0.0, -9.81), Vector3::zeros())
            .unwrap();
        gravity.step(0.01, &[0.0]).unwrap();
        force.step(0.01, &[0.0]).unwrap();
        assert!((gravity.positions[0] - force.positions[0]).abs() < 1e-12);
        assert!((gravity.velocities[0] - force.velocities[0]).abs() < 1e-12);

        let snapshot = force.snapshot();
        force.set_link_gravity_scale(1, 1.0).unwrap();
        force
            .set_link_external_wrench(1, Vector3::zeros(), Vector3::zeros())
            .unwrap();
        force.restore_snapshot(&snapshot).unwrap();
        assert_eq!(
            force.link_external_load(1),
            Some(LinkExternalLoad {
                force: Vector3::new(0.0, 0.0, -9.81),
                torque: Vector3::zeros(),
                gravity_scale: 0.0,
            })
        );
        assert!(force.set_link_gravity_scale(2, 1.0).is_err());
        assert!(force.set_link_gravity_scale(1, f64::NAN).is_err());
        assert!(
            force
                .set_link_external_wrench(1, Vector3::repeat(f64::INFINITY), Vector3::zeros())
                .is_err()
        );

        let mut torque = pendulum();
        let mut wrench = pendulum();
        torque.params.gravity = [0.0; 3];
        wrench.params.gravity = [0.0; 3];
        wrench
            .set_link_external_wrench(1, Vector3::zeros(), Vector3::y())
            .unwrap();
        torque.step(0.01, &[1.0]).unwrap();
        wrench.step(0.01, &[0.0]).unwrap();
        assert!((torque.velocities[0] - wrench.velocities[0]).abs() < 1e-12);
    }

