    #[test]
    fn joint_passive_force_matches_external_torque_and_restores() {
        let mut passive_world = pendulum();
        passive_world.params.gravity = [0.0; 3];
        passive_world.positions[0] = 0.2;
        passive_world.velocities[0] = 0.1;
        let passive = JointPassive {
            stiffness: 10.0,
            damping: 2.0,
            rest_position: 0.5,
        };
        assert!(passive_world.set_joint_passive(1, passive).is_err());
        assert!(
            passive_world
                .set_joint_passive(
                    0,
                    JointPassive {
                        damping: -1.0,
                        ..passive
                    }
                )
                .is_err()
        );
        passive_world.set_joint_passive(0, passive).unwrap();
        let snapshot = passive_world.snapshot();
        let pose = passive_world
            .articulation
            .pose(passive_world.root_pose, passive_world.positions.as_slice())
            .unwrap();
        let inertia = passive_world
            .articulation
            .dynamics(&pose, Vector3::zeros())
            .unwrap()
            .mass[(0, 0)];
        passive_world.step(0.001, &[0.0]).unwrap();
        let dt = 0.001;
        let expected = 0.1
            + dt * (2.8 - dt * passive.stiffness * 0.1)
                / (inertia + dt * passive.damping + dt * dt * passive.stiffness);
        assert!((passive_world.velocities[0] - expected).abs() < 1e-9);
        #[cfg(feature = "gpu-contact")]
        let solved_velocity = passive_world.velocities[0];
        passive_world
            .set_joint_passive(0, JointPassive::default())
            .unwrap();
        passive_world.restore_snapshot(&snapshot).unwrap();
        assert_eq!(passive_world.joint_passive(0), Some(passive));

        #[cfg(feature = "gpu-contact")]
        if let Ok(gpu) = GpuContactDevice::new() {
            let mut gpu_world = pendulum();
            gpu_world.params.gravity = [0.0; 3];
            gpu_world.positions[0] = 0.2;
            gpu_world.velocities[0] = 0.1;
            gpu_world.set_joint_passive(0, passive).unwrap();
            gpu_world.step_gpu(0.001, &[0.0], &gpu).unwrap();
            assert!((gpu_world.velocities[0] - solved_velocity).abs() < 1e-6);
        }
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn gpu_contact_mass_includes_signed_implicit_passive_diagonal() {
        use crate::gpu_articulated_mass_assembly::GpuArticulatedMassAssemblyBatch;

        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let mut world = pendulum();
        world.params.gravity = [0.0; 3];
        world.positions[0] = 0.2;
        world.velocities[0] = 0.1;
        world
            .set_joint_passive(
                0,
                JointPassive {
                    stiffness: 1.0,
                    damping: 0.0,
                    rest_position: 0.5,
                },
            )
            .unwrap();
        world
            .set_joint_nonlinear_passive(
                0,
                JointNonlinearPassive {
                    spring_quadratic: 10.0,
                    ..JointNonlinearPassive::default()
                },
            )
            .unwrap();
        let dt = 0.01;
        let system = world
            .generalized_contact_mass_assembly_system(dt, &[0.3])
            .unwrap();
        assert!(system.armature[0] < 0.0);
        let pending = world.prepare_contact_step(dt, &[0.3], None).unwrap();
        let velocity = world.current_generalized_velocity();
        let dynamics = world
            .articulation
            .generalized_dynamics(
                world.root_pose,
                world.positions.as_slice(),
                &velocity,
                world.floating,
                Vector3::from(world.params.gravity),
            )
            .unwrap();
        assert!(
            (system.force.clone() - (&pending.applied_force - dynamics.velocity_bias)).norm()
                < 1e-12
        );
        let batch =
            GpuArticulatedMassAssemblyBatch::new(gpu.device(), gpu.queue(), &[system]).unwrap();
        batch.submit_with_inverse();
        let inverse = batch.readback_inverse().unwrap().remove(0);
        assert!((inverse - pending.problem.inverse_mass).norm() < 2e-5);
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn gpu_contact_mass_includes_rotated_scene_inertia_and_static_slots() {
        use crate::gpu_articulated_mass_assembly::GpuArticulatedMassAssemblyBatch;

        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let mut world = pendulum();
        let _static_body = world.add_scene_body(scene_sphere(10.0, 0.0));
        let mut dynamic = SceneBody::new(
            Isometry3::from_parts(
                Translation3::new(4.0, 0.0, 10.0),
                UnitQuaternion::from_euler_angles(0.2, 0.3, -0.4),
            ),
            2.0,
            Matrix3::from_diagonal(&Vector3::new(1.0, 2.0, 3.0)),
            vec![SceneCollider::Sphere {
                center: Vector3::zeros(),
                radius: 0.2,
            }],
        )
        .unwrap();
        dynamic.angular_velocity = Vector3::new(0.3, -0.2, 0.4);
        dynamic.force = Vector3::new(1.0, 2.0, -3.0);
        let dynamic_body = world.add_scene_body(dynamic);
        let system = world
            .generalized_contact_mass_assembly_system(0.001, &[0.0])
            .unwrap();
        assert_eq!(system.force.len(), 7);
        assert_eq!(system.links.len(), 3);
        let body = &world.scene_bodies[dynamic_body];
        let inertia = system.links[2].inertia_world;
        let expected_linear = Vector3::from(world.params.gravity) * body.mass + body.force;
        let expected_angular = -body
            .angular_velocity
            .cross(&(inertia * body.angular_velocity));
        for axis in 0..3 {
            assert!((system.force[1 + axis] - expected_linear[axis]).abs() < 1e-12);
            assert!((system.force[4 + axis] - expected_angular[axis]).abs() < 1e-12);
        }
        let pending = world.prepare_contact_step(0.001, &[0.0], None).unwrap();
        assert_eq!(pending.problem.inverse_mass.shape(), (7, 7));
        let batch =
            GpuArticulatedMassAssemblyBatch::new(gpu.device(), gpu.queue(), &[system]).unwrap();
        batch.submit_with_inverse();
        let inverse = batch.readback_inverse().unwrap().remove(0);
        assert!((inverse - pending.problem.inverse_mass).norm() < 2e-5);
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn articulated_ground_contact_uses_device_inverse_mass_response() {
        use crate::gpu_articulated_mass_assembly::GpuArticulatedMassAssemblyBatch;
        use crate::gpu_contact_solver::{GpuContactSolver, GpuDeviceMassContactRequest};

        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let mut world = pendulum();
        world.root_pose.translation.vector.z = 0.2;
        world.colliders.push(LinkSphere {
            link: 1,
            center: Vector3::new(1.0, 0.0, 0.0),
            radius: 0.2,
        });
        world.velocities[0] = 0.2;
        world
            .set_joint_passive(
                0,
                JointPassive {
                    stiffness: 10.0,
                    damping: 2.0,
                    rest_position: 0.1,
                },
            )
            .unwrap();
        let dt = 0.001;
        let system = world
            .generalized_contact_mass_assembly_system(dt, &[0.0])
            .unwrap();
        let pending = world.prepare_contact_step(dt, &[0.0], None).unwrap();
        assert!(!pending.problem.contacts.is_empty());
        let expected = solve_contacts(
            &pending.problem,
            pending.solve_params,
            Some(&pending.warm_start),
        )
        .unwrap();
        let mass =
            GpuArticulatedMassAssemblyBatch::new(gpu.device(), gpu.queue(), &[system]).unwrap();
        let solver = GpuContactSolver::new(gpu.device());
        let mut encoder = gpu.device().create_command_encoder(&Default::default());
        mass.encode_with_inverse(&mut encoder);
        let output = solver
            .encode_device_inverse_mass(
                gpu.device(),
                &mut encoder,
                GpuDeviceMassContactRequest {
                    inverse_mass: mass.inverse_buffer().unwrap(),
                    inverse_range: mass.inverse_ranges()[0].clone(),
                    velocity: &pending.problem.velocity,
                    contacts: &pending.problem.contacts,
                    params: pending.solve_params,
                    warm_start: Some(&pending.warm_start),
                },
            )
            .unwrap()
            .unwrap();
        let readback = output.encode_readback(gpu.device(), &mut encoder);
        let _ = gpu.queue().submit(Some(encoder.finish()));
        let actual = readback.finish(gpu.device()).unwrap();
        assert!((&actual.velocity - &expected.velocity).norm() < 2e-5);
        for (actual, expected) in actual.impulses.iter().zip(&expected.impulses) {
            assert!((actual.normal - expected.normal).abs() < 2e-5);
            for (actual, expected) in actual.tangents.iter().zip(expected.tangents.iter()) {
                assert!((actual - expected).abs() < 2e-5);
            }
        }
    }

