    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_gpu_joint_friction_updates_without_state_reset() {
        use crate::gpu_articulated_dynamics::GpuArticulatedDynamicsBatch;

        let mut tested = 0;
        for backend in [wgpu::Backends::VULKAN, wgpu::Backends::DX12] {
            let Ok(context) = GpuContactDevice::new_with_backends(backend) else {
                continue;
            };
            tested += 1;
            let mut cpu = pendulum();
            cpu.params.gravity = [0.0; 3];
            cpu.set_joint_friction(0, 1.0).unwrap();
            let mut gpu_world = pendulum();
            gpu_world.params.gravity = [0.0; 3];
            gpu_world.set_joint_friction(0, 1.0).unwrap();
            let input = gpu_world.gpu_dynamics_input(&[0.5]).unwrap();
            let batch =
                GpuArticulatedDynamicsBatch::new(&context, core::slice::from_ref(&input), 0.001)
                    .unwrap();
            assert!(batch.update_joint_frictions(&[vec![f64::NAN]]).is_err());
            cpu.step(0.001, &[0.5]).unwrap();
            batch.submit_steps(1).unwrap();
            assert!((batch.readback().unwrap()[0].velocities[0] - cpu.velocities[0]).abs() < 1e-5);
            cpu.set_joint_friction(0, 0.0).unwrap();
            cpu.step(0.001, &[0.5]).unwrap();
            batch.update_joint_frictions(&[vec![0.0]]).unwrap();
            batch.submit_steps(1).unwrap();
            let state = batch.readback().unwrap();
            assert!((state[0].velocities[0] - cpu.velocities[0]).abs() < 2e-5);
            assert!(state[0].velocities[0] > 0.0);

            let mut reserved_world = pendulum();
            reserved_world.params.gravity = [0.0; 3];
            let mut reserved_input = reserved_world.gpu_dynamics_input(&[0.5]).unwrap();
            assert!(reserved_input.joint_friction.is_empty());
            reserved_input.joint_friction = vec![0.0];
            let reserved_batch = GpuArticulatedDynamicsBatch::new(
                &context,
                core::slice::from_ref(&reserved_input),
                0.001,
            )
            .unwrap();
            reserved_batch.update_joint_frictions(&[vec![1.0]]).unwrap();
            reserved_batch.submit_steps(1).unwrap();
            assert!(reserved_batch.readback().unwrap()[0].velocities[0].abs() < 1e-5);

            let paired =
                GpuArticulatedDynamicsBatch::new(&context, &[input.clone(), input.clone()], 0.001)
                    .unwrap();
            assert!(
                paired
                    .update_joint_frictions(&[vec![0.0], vec![f64::NAN]])
                    .is_err()
            );
            paired.submit_steps(1).unwrap();
            assert!(
                paired
                    .readback()
                    .unwrap()
                    .iter()
                    .all(|state| state.velocities[0].abs() < 1e-5)
            );
        }
        assert!(tested > 0);
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_link_constraints_match_cpu() {
        use crate::gpu_articulated_dynamics::GpuArticulatedDynamicsBatch;
        let build = |case: usize| {
            let rotational = matches!(case, 1 | 3 | 4 | 8 | 9);
            let articulation = Articulation::new(
                vec![
                    LinkSpec {
                        mass: 1.0,
                        center_of_mass: Vector3::zeros(),
                        inertia: Matrix3::identity() * 0.1
                    };
                    3
                ],
                (0..2)
                    .map(|index| JointSpec {
                        parent: 0,
                        child: index + 1,
                        origin: Isometry3::identity(),
                        kind: if rotational {
                            JointKind::Revolute
                        } else {
                            JointKind::Prismatic
                        },
                        axis: Vector3::z(),
                        limits: None,
                    })
                    .collect(),
                0,
            )
            .unwrap();
            let root = if case == 4 || case == 9 {
                Isometry3::from_parts(
                    Translation3::new(0.0, 0.0, 2.0),
                    UnitQuaternion::from_euler_angles(0.2, -0.4, 0.3),
                )
            } else {
                Isometry3::translation(0.0, 0.0, if case == 5 { 0.2 } else { 2.0 })
            };
            let spheres = if case == 5 {
                vec![LinkSphere {
                    link: 1,
                    center: Vector3::zeros(),
                    radius: 0.25,
                }]
            } else {
                Vec::new()
            };
            let mut world = ArticulatedWorld::new(
                articulation,
                root,
                spheres,
                ArticulatedWorldParams {
                    gravity: [0.0; 3],
                    max_substep: 0.001,
                    ..Default::default()
                },
            )
            .unwrap();
            if matches!(case, 7..=9) {
                let body_pose = Isometry3::from_parts(
                    Translation3::new(0.3, -0.2, 2.1),
                    UnitQuaternion::from_euler_angles(0.4, -0.2, 0.3),
                );
                let body = world.add_scene_body(
                    SceneBody::new(
                        body_pose,
                        0.0,
                        Matrix3::zeros(),
                        vec![SceneCollider::Sphere {
                            center: Vector3::new(100.0, 0.0, 0.0),
                            radius: 0.05,
                        }],
                    )
                    .unwrap(),
                );
                if case == 7 {
                    let local = body_pose.inverse_transform_point(&Point3::new(0.0, 0.0, 2.001));
                    world
                        .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                            link: 1,
                            link_point: [0.0; 3],
                            body,
                            body_point: [local.x, local.y, local.z],
                        }])
                        .unwrap();
                } else {
                    let frame = Isometry3::from_parts(
                        Translation3::new(0.2, 0.1, -0.05),
                        UnitQuaternion::from_euler_angles(0.3, 0.1, -0.2),
                    );
                    world
                        .set_link_scene_fixed_constraints(vec![LinkSceneFixedConstraint {
                            link: 1,
                            link_frame: frame,
                            body,
                            body_frame: body_pose.inverse() * root * frame,
                        }])
                        .unwrap();
                    world.positions[0] = 0.001;
                }
            } else if matches!(case, 1 | 3 | 4 | 8 | 9) {
                let frame = if case == 4 {
                    Isometry3::from_parts(
                        Translation3::new(0.2, 0.1, -0.05),
                        UnitQuaternion::from_euler_angles(0.3, 0.0, 0.0),
                    )
                } else {
                    Isometry3::identity()
                };
                world
                    .set_link_fixed_constraints(vec![LinkFixedConstraint {
                        link_a: 1,
                        frame_a: frame,
                        link_b: if case == 3 { None } else { Some(2) },
                        frame_b: if case == 3 { root } else { frame },
                    }])
                    .unwrap();
                if case == 3 {
                    world.positions[0] = 0.001;
                }
            } else {
                world
                    .set_link_point_constraints(vec![LinkPointConstraint {
                        link_a: 1,
                        point_a: [0.0; 3],
                        link_b: if case == 2 || case == 6 {
                            None
                        } else {
                            Some(2)
                        },
                        point_b: if case == 2 {
                            [0.0, 0.0, 2.001]
                        } else if case == 6 {
                            [0.001, 0.0, 2.0]
                        } else {
                            [0.0; 3]
                        },
                    }])
                    .unwrap();
            }
            world
        };
        let cases = [0, 1, 2, 3, 4, 5, 7, 8, 9];
        let efforts = cases
            .iter()
            .map(|&case| {
                if matches!(case, 0 | 1 | 4) {
                    vec![1.0, 0.0]
                } else {
                    vec![0.0; 2]
                }
            })
            .collect::<Vec<_>>();
        let worlds = cases.iter().map(|&case| build(case)).collect::<Vec<_>>();
        let inputs = worlds
            .iter()
            .zip(&efforts)
            .map(|(world, efforts)| world.gpu_dynamics_input(efforts).unwrap())
            .collect::<Vec<_>>();
        assert_eq!(inputs[6].link_point_constraints.len(), 1);
        assert!((inputs[6].link_point_constraints[0].point_b[2] - 2.001).abs() < 1e-12);
        assert_eq!(inputs[7].link_fixed_constraints.len(), 1);
        assert_eq!(inputs[8].link_fixed_constraints.len(), 1);
        let mut moving = build(7);
        moving.scene_bodies[0].linear_velocity = Vector3::x();
        assert!(moving.gpu_dynamics_input(&[0.0; 2]).is_err());
        let mut singular_reference = build(6);
        assert!(singular_reference.step(0.001, &[0.0; 2]).is_err());
        let singular_world = build(6);
        let singular_input = singular_world.gpu_dynamics_input(&[0.0; 2]).unwrap();
        let mut tested = 0;
        for backend in [wgpu::Backends::VULKAN, wgpu::Backends::DX12] {
            let Ok(context) = GpuContactDevice::new_with_backends(backend) else {
                continue;
            };
            eprintln!("Resident link constraints on {backend:?}");
            tested += 1;
            let batch = GpuArticulatedDynamicsBatch::new(&context, &inputs, 0.001).unwrap();
            let mut reference = cases.iter().map(|&case| build(case)).collect::<Vec<_>>();
            for steps in [1, 31] {
                batch.submit_steps(steps).unwrap();
                for _ in 0..steps {
                    for (world, effort) in reference.iter_mut().zip(&efforts) {
                        world.step(0.001, effort).unwrap();
                    }
                }
                let states = batch.readback().unwrap();
                for (case, (state, world)) in states.iter().zip(&reference).enumerate() {
                    assert!(
                        (&state.positions - &world.positions).norm() < 2e-4,
                        "case {case}: positions {:?} versus {:?}",
                        state.positions,
                        world.positions
                    );
                    assert!(
                        (&state.velocities - &world.velocities).norm() < 2e-3,
                        "case {case}: velocities {:?} versus {:?}",
                        state.velocities,
                        world.velocities
                    );
                }
            }
            let changed_root = Isometry3::translation(0.0, 0.0, 1.999);
            batch.set_root_pose(6, changed_root).unwrap();
            reference[6].root_pose = changed_root;
            batch.submit_steps(1).unwrap();
            reference[6].step(0.001, &efforts[6]).unwrap();
            let moved = batch.readback().unwrap();
            assert!((&moved[6].positions - &reference[6].positions).norm() < 2e-4);
            assert!((&moved[6].velocities - &reference[6].velocities).norm() < 2e-3);
            assert!(moved[6].velocities[0] > 0.1);
            let singular = GpuArticulatedDynamicsBatch::new(
                &context,
                core::slice::from_ref(&singular_input),
                0.001,
            )
            .unwrap();
            singular.submit_steps(1).unwrap();
            assert!(singular.readback().is_err());
        }
        assert!(tested > 0);
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_joint_equalities_match_cpu_with_contact() {
        use crate::gpu_articulated_dynamics::GpuArticulatedDynamicsBatch;
        let build = |case: usize| {
            let articulation = Articulation::new(
                vec![
                    LinkSpec {
                        mass: 1.0,
                        center_of_mass: Vector3::zeros(),
                        inertia: Matrix3::identity() * 0.1
                    };
                    3
                ],
                (0..2)
                    .map(|index| JointSpec {
                        parent: 0,
                        child: index + 1,
                        origin: Isometry3::identity(),
                        kind: JointKind::Prismatic,
                        axis: Vector3::z(),
                        limits: None,
                    })
                    .collect(),
                0,
            )
            .unwrap();
            let spheres = if case == 4 {
                vec![LinkSphere {
                    link: 1,
                    center: Vector3::zeros(),
                    radius: 0.25,
                }]
            } else {
                Vec::new()
            };
            let mut world = ArticulatedWorld::new(
                articulation,
                Isometry3::translation(0.0, 0.0, if case == 4 { 0.2 } else { 2.0 }),
                spheres,
                ArticulatedWorldParams {
                    gravity: [0.0; 3],
                    max_substep: 0.001,
                    ..Default::default()
                },
            )
            .unwrap();
            if case == 2 {
                let coupling = JointPolynomialCoupling {
                    source: Some(0),
                    follower: 1,
                    coefficients: [0.002, 0.5, -0.25, 0.1, 0.05],
                    follower_reference: -0.2,
                    source_reference: 0.1,
                };
                world.positions[0] = 0.3;
                world.positions[1] = coupling.follower_reference
                    + coupling.value_and_derivative(world.positions[0]).unwrap().0;
                world
                    .set_joint_polynomial_couplings(vec![coupling])
                    .unwrap();
            } else if case == 3 {
                world
                    .set_joint_polynomial_couplings(vec![JointPolynomialCoupling {
                        source: None,
                        follower: 1,
                        coefficients: [0.001, 0.0, 0.0, 0.0, 0.0],
                        follower_reference: 0.0,
                        source_reference: 0.7,
                    }])
                    .unwrap();
            } else {
                world
                    .set_joint_couplings(vec![JointCoupling {
                        source: 0,
                        follower: 1,
                        multiplier: -2.0,
                        offset: if case == 1 { 0.001 } else { 0.0 },
                    }])
                    .unwrap();
            }
            world
        };
        let efforts = (0..5)
            .map(|case| {
                if case == 0 || case == 2 {
                    vec![1.0, 0.0]
                } else {
                    vec![0.0, 0.0]
                }
            })
            .collect::<Vec<_>>();
        let worlds = (0..5).map(build).collect::<Vec<_>>();
        let inputs = worlds
            .iter()
            .zip(&efforts)
            .map(|(world, efforts)| world.gpu_dynamics_input(efforts).unwrap())
            .collect::<Vec<_>>();
        assert!(inputs.iter().all(|input| input.joint_couplings.len() == 1));
        let mut tested = 0;
        for backend in [wgpu::Backends::VULKAN, wgpu::Backends::DX12] {
            let Ok(context) = GpuContactDevice::new_with_backends(backend) else {
                continue;
            };
            eprintln!("Resident joint equalities on {backend:?}");
            tested += 1;
            let batch = GpuArticulatedDynamicsBatch::new(&context, &inputs, 0.001).unwrap();
            let mut reference = (0..5).map(build).collect::<Vec<_>>();
            for steps in [1, 31] {
                batch.submit_steps(steps).unwrap();
                for _ in 0..steps {
                    for (world, effort) in reference.iter_mut().zip(&efforts) {
                        world.step(0.001, effort).unwrap();
                    }
                }
                let states = batch.readback().unwrap();
                for (case, (state, world)) in states.iter().zip(&reference).enumerate() {
                    assert!(
                        (&state.positions - &world.positions).norm() < 2e-4,
                        "case {case}: positions {:?} versus {:?}",
                        state.positions,
                        world.positions
                    );
                    assert!(
                        (&state.velocities - &world.velocities).norm() < 2e-3,
                        "case {case}: velocities {:?} versus {:?}",
                        state.velocities,
                        world.velocities
                    );
                }
            }
        }
        assert!(tested > 0);
    }

    #[test]
    fn joint_coupling_transmits_force_and_restores() {
        let links = vec![
            LinkSpec {
                mass: 1.0,
                center_of_mass: Vector3::zeros(),
                inertia: Matrix3::identity() * 0.1
            };
            3
        ];
        let joints = [Vector3::x(), Vector3::y()]
            .into_iter()
            .enumerate()
            .map(|(index, axis)| JointSpec {
                parent: 0,
                child: index + 1,
                origin: Isometry3::identity(),
                kind: JointKind::Prismatic,
                axis,
                limits: None,
            })
            .collect();
        let articulation = Articulation::new(links, joints, 0).unwrap();
        let params = ArticulatedWorldParams {
            gravity: [0.0; 3],
            max_substep: 0.001,
            ..Default::default()
        };
        let mut cpu =
            ArticulatedWorld::new(articulation, Isometry3::identity(), Vec::new(), params).unwrap();
        let coupling = JointCoupling {
            source: 0,
            follower: 1,
            multiplier: -2.0,
            offset: 0.0,
        };
        assert!(
            cpu.set_joint_couplings(vec![JointCoupling {
                follower: 0,
                ..coupling
            }])
            .is_err()
        );
        cpu.set_joint_couplings(vec![coupling]).unwrap();
        let snapshot = cpu.snapshot();
        cpu.step(0.001, &[1.0, 0.0]).unwrap();
        assert!((cpu.velocities[1] + 2.0 * cpu.velocities[0]).abs() < 1e-10);
        assert!((cpu.velocities[0] - 0.0002).abs() < 1e-9);
        #[cfg(feature = "gpu-contact")]
        let expected = cpu.velocities.clone();
        cpu.set_joint_couplings(Vec::new()).unwrap();
        cpu.restore_snapshot(&snapshot).unwrap();
        assert_eq!(cpu.joint_couplings(), &[coupling]);
        #[cfg(feature = "gpu-contact")]
        if let Ok(gpu) = GpuContactDevice::new() {
            cpu.step_gpu(0.001, &[1.0, 0.0], &gpu).unwrap();
            assert!((cpu.velocities[0] - expected[0]).abs() < 1e-6);
            assert!((cpu.velocities[1] - expected[1]).abs() < 1e-6);
        }
        cpu.restore_snapshot(&snapshot).unwrap();
        cpu.set_joint_couplings(vec![JointCoupling {
            offset: 0.001,
            ..coupling
        }])
        .unwrap();
        cpu.step(0.001, &[0.0, 0.0]).unwrap();
        assert!((cpu.velocities[1] + 2.0 * cpu.velocities[0] - 0.2).abs() < 1e-8);
    }

    #[test]
    fn loop_ball_constraint_transfers_impulse_between_branches() {
        let links = vec![
            LinkSpec {
                mass: 1.0,
                center_of_mass: Vector3::zeros(),
                inertia: Matrix3::identity() * 0.1,
            };
            3
        ];
        let joints = vec![
            JointSpec {
                parent: 0,
                child: 1,
                origin: Isometry3::identity(),
                kind: JointKind::Revolute,
                axis: Vector3::z(),
                limits: None,
            },
            JointSpec {
                parent: 0,
                child: 2,
                origin: Isometry3::identity(),
                kind: JointKind::Prismatic,
                axis: Vector3::y(),
                limits: None,
            },
        ];
        let articulation = Articulation::new(links, joints, 0).unwrap();
        let params = ArticulatedWorldParams {
            gravity: [0.0; 3],
            ..Default::default()
        };
        let mut world =
            ArticulatedWorld::new(articulation, Isometry3::identity(), Vec::new(), params).unwrap();
        let constraint = LinkPointConstraint {
            link_a: 1,
            point_a: [1.0, 0.0, 0.0],
            link_b: Some(2),
            point_b: [1.0, 0.0, 0.0],
        };
        assert!(
            world
                .set_link_point_constraints(vec![LinkPointConstraint {
                    link_b: Some(1),
                    ..constraint
                }])
                .is_err()
        );
        assert!(
            world
                .set_link_point_constraints(vec![LinkPointConstraint {
                    point_a: [f64::NAN, 0.0, 0.0],
                    ..constraint
                }])
                .is_err()
        );
        world.set_link_point_constraints(vec![constraint]).unwrap();
        let snapshot = world.snapshot();
        world.step(0.001, &[1.0, 0.0]).unwrap();
        assert!(world.velocities[0] > 0.0);
        assert!((world.velocities[1] - world.velocities[0]).abs() < 1e-9);
        #[cfg(feature = "gpu-contact")]
        let expected = world.velocities.clone();
        world.set_link_point_constraints(Vec::new()).unwrap();
        world.restore_snapshot(&snapshot).unwrap();
        assert_eq!(world.link_point_constraints(), &[constraint]);
        #[cfg(feature = "gpu-contact")]
        if let Ok(gpu) = GpuContactDevice::new() {
            world.step_gpu(0.001, &[1.0, 0.0], &gpu).unwrap();
            assert!((world.velocities[0] - expected[0]).abs() < 1e-6);
            assert!((world.velocities[1] - expected[1]).abs() < 1e-6);
        }
    }

