    #[test]
    fn fixed_world_frame_corrects_all_six_floating_axes() {
        let articulation = Articulation::new(
            vec![LinkSpec {
                mass: 1.0,
                center_of_mass: Vector3::zeros(),
                inertia: Matrix3::identity(),
            }],
            Vec::new(),
            0,
        )
        .unwrap();
        let initial_pose = Isometry3::from_parts(
            Translation3::new(0.1, -0.1, 0.1),
            UnitQuaternion::from_scaled_axis(Vector3::new(0.1, -0.1, 0.1)),
        );
        let mut world = ArticulatedWorld::new_floating(
            articulation,
            initial_pose,
            Vec::new(),
            ArticulatedWorldParams {
                gravity: [0.0; 3],
                ..Default::default()
            },
        )
        .unwrap();
        world
            .set_link_fixed_constraints(vec![LinkFixedConstraint {
                link_a: 0,
                frame_a: Isometry3::identity(),
                link_b: None,
                frame_b: Isometry3::identity(),
            }])
            .unwrap();
        #[cfg(feature = "gpu-contact")]
        let snapshot = world.snapshot();
        world.step(0.001, &[]).unwrap();
        assert!(world.base_linear_velocity.x < 0.0);
        assert!(world.base_linear_velocity.y > 0.0);
        assert!(world.base_linear_velocity.z < 0.0);
        assert!(world.base_angular_velocity.x < 0.0);
        assert!(world.base_angular_velocity.y > 0.0);
        assert!(world.base_angular_velocity.z < 0.0);
        assert!(world.root_pose.translation.vector.norm() < initial_pose.translation.vector.norm());
        assert!(world.root_pose.rotation.angle() < initial_pose.rotation.angle());
        #[cfg(feature = "gpu-contact")]
        if let Ok(gpu) = GpuContactDevice::new() {
            let expected_pose = world.root_pose;
            let expected_linear = world.base_linear_velocity;
            let expected_angular = world.base_angular_velocity;
            world.restore_snapshot(&snapshot).unwrap();
            world.step_gpu(0.001, &[], &gpu).unwrap();
            assert!(
                (world.root_pose.translation.vector - expected_pose.translation.vector).norm()
                    < 1e-5
            );
            assert!((world.root_pose.rotation * expected_pose.rotation.inverse()).angle() < 1e-5);
            assert!((world.base_linear_velocity - expected_linear).norm() < 1e-5);
            assert!((world.base_angular_velocity - expected_angular).norm() < 1e-5);
        }
    }

    fn scene_constraint_world(kind: JointKind) -> ArticulatedWorld {
        let articulation = Articulation::new(
            vec![
                LinkSpec {
                    mass: 1.0,
                    center_of_mass: Vector3::zeros(),
                    inertia: Matrix3::identity() * 0.1,
                };
                2
            ],
            vec![JointSpec {
                parent: 0,
                child: 1,
                origin: Isometry3::identity(),
                kind,
                axis: if kind == JointKind::Prismatic {
                    Vector3::x()
                } else {
                    Vector3::z()
                },
                limits: None,
            }],
            0,
        )
        .unwrap();
        ArticulatedWorld::new(
            articulation,
            Isometry3::translation(0.0, 0.0, 10.0),
            Vec::new(),
            ArticulatedWorldParams {
                gravity: [0.0; 3],
                ..Default::default()
            },
        )
        .unwrap()
    }

    #[test]
    fn link_scene_ball_constraint_transfers_impulse_and_tracks_removal() {
        let mut world = scene_constraint_world(JointKind::Prismatic);
        let first = world.add_scene_body(scene_sphere(20.0, 1.0));
        let second = world.add_scene_body(scene_sphere(10.0, 1.0));
        let constraint = LinkScenePointConstraint {
            link: 1,
            link_point: [0.0; 3],
            body: second,
            body_point: [0.0; 3],
        };
        assert!(
            world
                .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                    body: 99,
                    ..constraint
                }])
                .is_err()
        );
        assert!(
            world
                .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                    link_point: [f64::NAN, 0.0, 0.0],
                    ..constraint
                }])
                .is_err()
        );
        world
            .set_link_scene_point_constraints(vec![constraint])
            .unwrap();
        let snapshot = world.snapshot();
        world.step(0.001, &[1.0]).unwrap();
        assert!(world.velocities[0] > 0.0);
        assert!((world.velocities[0] - world.scene_bodies[second].linear_velocity.x).abs() < 1e-9);
        #[cfg(feature = "gpu-contact")]
        let expected = (
            world.velocities[0],
            world.scene_bodies[second].linear_velocity.x,
        );
        world.restore_snapshot(&snapshot).unwrap();
        assert_eq!(world.link_scene_point_constraints(), &[constraint]);
        #[cfg(feature = "gpu-contact")]
        if let Ok(gpu) = GpuContactDevice::new() {
            world.step_gpu(0.001, &[1.0], &gpu).unwrap();
            assert!((world.velocities[0] - expected.0).abs() < 1e-6);
            assert!((world.scene_bodies[second].linear_velocity.x - expected.1).abs() < 1e-6);
        }
        assert!(world.remove_scene_body(first));
        assert_eq!(world.link_scene_point_constraints()[0].body, 0);
        assert!(world.remove_scene_body(0));
        assert!(world.link_scene_point_constraints().is_empty());
    }

