    #[cfg(feature = "gpu-contact")]
    #[test]
    fn composed_moving_point_anchor_initial_input_drives_gpu_link() {
        let mut world = scene_constraint_world(JointKind::Prismatic);
        let mut body = scene_sphere(10.0, 0.0);
        body.pose = world.root_pose;
        body.colliders.clear();
        let moving = world.add_scene_body(body);
        world
            .set_scene_body_kinematic_motion(moving, Some((Vector3::x() * 0.2, Vector3::zeros())))
            .unwrap();
        world
            .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                link: 1,
                link_point: [0.0; 3],
                body: moving,
                body_point: [0.0; 3],
            }])
            .unwrap();
        let source = world.compose_scene_dynamics().unwrap();
        let input = world.gpu_scene_dynamics_input(&source, &[0.0]).unwrap();
        assert_eq!(input.external_constraint_bodies.as_ref().unwrap().len(), 1);
        let gpu = GpuContactDevice::new_with_backends(wgpu::Backends::VULKAN).unwrap();
        let batch = crate::gpu_articulated_dynamics::GpuArticulatedDynamicsBatch::new(
            &gpu,
            &[input],
            0.001,
        )
        .unwrap();
        batch.submit_steps(100).unwrap();
        let state = batch.readback().unwrap().remove(0);
        assert!((state.positions[0] - 0.02).abs() < 1e-5, "{state:?}");
        assert!((state.velocities[0] - 0.2).abs() < 1e-5, "{state:?}");
        let frame = batch.readback_prescribed_constraint_frames().unwrap()[0][0];
        assert!((frame.translation.vector - Vector3::new(0.02, 0.0, 10.0)).norm() < 1e-5);
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_batch_rotating_fixed_and_offset_point_anchors_sync() {
        let mut worlds = Vec::new();
        for fixed in [true, false] {
            let mut world = scene_constraint_world(JointKind::Revolute);
            let mut body = scene_sphere(10.0, 0.0);
            body.pose = world.root_pose;
            body.colliders.clear();
            let moving = world.add_scene_body(body);
            world
                .set_scene_body_kinematic_motion(
                    moving,
                    Some((Vector3::zeros(), Vector3::z() * 0.2)),
                )
                .unwrap();
            if fixed {
                world
                    .set_link_scene_fixed_constraints(vec![LinkSceneFixedConstraint {
                        link: 1,
                        link_frame: Isometry3::identity(),
                        body: moving,
                        body_frame: Isometry3::identity(),
                    }])
                    .unwrap();
            } else {
                world
                    .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                        link: 1,
                        link_point: [1.0, 0.0, 0.0],
                        body: moving,
                        body_point: [1.0, 0.0, 0.0],
                    }])
                    .unwrap();
            }
            let mut stationary = scene_sphere(10.0, 0.0);
            stationary.pose.translation.vector.x = 100.0;
            let _ = world.add_scene_body(stationary);
            worlds.push(world);
        }
        let gpu = GpuContactDevice::new_with_backends(wgpu::Backends::VULKAN).unwrap();
        let mut session =
            crate::gpu_scene_dynamics::GpuSceneDynamicsBatch::new(&worlds, &gpu, 0.001).unwrap();
        for iteration in 0..2 {
            let _ = session.step(&mut worlds, &[&[0.0], &[0.0]], 50).unwrap();
            if iteration == 0 {
                for world in &mut worlds {
                    world.scene_bodies[1].pose.translation.vector.x = 101.0;
                }
                session.update_static_scene_poses(&worlds).unwrap();
            }
        }
        for world in &worlds {
            assert!((world.positions[0] - 0.02).abs() < 1e-5);
            assert!((world.velocities[0] - 0.2).abs() < 5e-5);
            let body = &world.scene_bodies[0];
            assert!((body.pose.rotation.scaled_axis().z - 0.02).abs() < 1e-5);
            assert!((body.pose.translation.vector - Vector3::new(0.0, 0.0, 10.0)).norm() < 1e-6);
        }
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_batch_moving_point_anchors_sync_and_reject_external_edits() {
        let mut worlds = Vec::new();
        for speed in [0.2, 0.0, -0.1] {
            let mut world = scene_constraint_world(JointKind::Prismatic);
            let mut body = scene_sphere(10.0, 0.0);
            body.pose = world.root_pose;
            body.colliders.clear();
            let moving = world.add_scene_body(body);
            world
                .set_scene_body_kinematic_motion(
                    moving,
                    Some((Vector3::x() * speed, Vector3::zeros())),
                )
                .unwrap();
            world
                .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                    link: 1,
                    link_point: [0.0; 3],
                    body: moving,
                    body_point: [0.0; 3],
                }])
                .unwrap();
            let mut stationary = scene_sphere(10.0, 0.0);
            stationary.pose.translation.vector.x = 100.0;
            let _ = world.add_scene_body(stationary);
            worlds.push(world);
        }
        let gpu = GpuContactDevice::new_with_backends(wgpu::Backends::VULKAN).unwrap();
        let mut session =
            crate::gpu_scene_dynamics::GpuSceneDynamicsBatch::new(&worlds, &gpu, 0.001).unwrap();
        for iteration in 0..2 {
            let _ = session
                .step(&mut worlds, &[&[0.0], &[0.0], &[0.0]], 50)
                .unwrap();
            if iteration == 0 {
                worlds[0].scene_bodies[1].pose.translation.vector.x = 101.0;
                session.update_static_scene_poses(&worlds).unwrap();
            }
        }
        for (world, speed) in worlds.iter().zip([0.2, 0.0, -0.1]) {
            assert!((world.positions[0] - speed * 0.1).abs() < 1e-5);
            assert!((world.velocities[0] - speed).abs() < 1e-5);
            assert!((world.scene_bodies[0].pose.translation.vector.x - speed * 0.1).abs() < 1e-5);
        }
        let before: Vec<_> = worlds.iter().map(|world| world.positions.clone()).collect();
        worlds[1]
            .set_scene_body_kinematic_motion(0, Some((Vector3::x() * 0.3, Vector3::zeros())))
            .unwrap();
        assert!(matches!(
            session.step(&mut worlds, &[&[0.0], &[0.0], &[0.0]], 1),
            Err(crate::gpu_scene_dynamics::GpuSceneDynamicsError::WorldChanged)
        ));
        for (world, expected) in worlds.iter().zip(before) {
            assert_eq!(world.positions, expected);
        }
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_indexed_scene_motion_drives_links_and_synchronizes_body_poses() {
        let mut worlds = Vec::new();
        for kind in 0..3 {
            let mut world = scene_constraint_world(JointKind::Prismatic);
            world.root_pose = Isometry3::from_parts(
                Translation3::new(0.0, 0.0, 1.0),
                UnitQuaternion::from_axis_angle(&Vector3::y_axis(), -core::f64::consts::FRAC_PI_2),
            );
            world.params.friction = 0.0;
            world.colliders.push(LinkSphere {
                link: 1,
                center: Vector3::x() * 0.5,
                radius: 0.5,
            });
            let collider = if kind == 1 {
                SceneCollider::Polyline {
                    origin: Isometry3::identity(),
                    geometry: PolylineGeometry::new(
                        vec![-Vector3::x(), Vector3::x()],
                        vec![[0, 1]],
                    )
                    .unwrap(),
                }
            } else if kind == 2 {
                SceneCollider::HeightField {
                    origin: Isometry3::identity(),
                    geometry: HeightFieldGeometry::new(
                        2,
                        2,
                        vec![0.0; 4],
                        Vector3::new(10.0, 10.0, 1.0),
                    )
                    .unwrap(),
                }
            } else {
                SceneCollider::TriangleMesh {
                    origin: Isometry3::identity(),
                    geometry: TriangleMeshGeometry::new(
                        vec![
                            Vector3::new(-5.0, -5.0, 0.0),
                            Vector3::new(5.0, -5.0, 0.0),
                            Vector3::new(0.0, 5.0, 0.0),
                        ],
                        vec![[0, 1, 2]],
                    )
                    .unwrap(),
                }
            };
            let stationary_shape = collider.clone();
            let body = world.add_scene_body(
                SceneBody::new(
                    Isometry3::translation(0.0, 0.0, 1.0),
                    0.0,
                    Matrix3::identity(),
                    vec![collider],
                )
                .unwrap(),
            );
            world
                .set_scene_body_kinematic_motion(body, Some((Vector3::z() * 0.2, Vector3::zeros())))
                .unwrap();
            let _ = world.add_scene_body(
                SceneBody::new(
                    Isometry3::translation(100.0, 0.0, 1.0),
                    0.0,
                    Matrix3::identity(),
                    vec![stationary_shape],
                )
                .unwrap(),
            );
            worlds.push(world);
        }
        let gpu = GpuContactDevice::new_with_backends(wgpu::Backends::VULKAN).unwrap();
        let mut session =
            crate::gpu_scene_dynamics::GpuSceneDynamicsBatch::new(&worlds, &gpu, 0.001).unwrap();
        for iteration in 0..2 {
            let _ = session
                .step(&mut worlds, &[&[0.0], &[0.0], &[0.0]], 50)
                .unwrap();
            if iteration == 0 {
                for world in &mut worlds {
                    world.scene_bodies[1].pose.translation.vector.x = 101.0;
                }
                session.update_static_scene_poses(&worlds).unwrap();
            }
        }
        for world in &worlds {
            assert!(
                (world.positions[0] - 0.02).abs() < 1e-5,
                "{:?}",
                world.positions
            );
            assert!(
                (world.velocities[0] - 0.2).abs() < 5e-5,
                "{:?}",
                world.velocities
            );
            assert!((world.scene_bodies[0].pose.translation.vector.z - 1.02).abs() < 1e-5);
        }
        let before: Vec<_> = worlds
            .iter()
            .map(|world| (world.positions.clone(), world.scene_bodies[0].pose))
            .collect();
        worlds[2]
            .set_scene_body_kinematic_motion(0, Some((Vector3::z() * 0.3, Vector3::zeros())))
            .unwrap();
        assert!(matches!(
            session.step(&mut worlds, &[&[0.0], &[0.0], &[0.0]], 1),
            Err(crate::gpu_scene_dynamics::GpuSceneDynamicsError::WorldChanged)
        ));
        for (world, (positions, pose)) in worlds.iter().zip(before) {
            assert_eq!(world.positions, positions);
            assert_eq!(world.scene_bodies[0].pose, pose);
        }
    }

