    fn resident_moving_point_anchor_synchronizes_consecutive_steps() {
        let mut world = scene_constraint_world(JointKind::Prismatic);
        let mut body = scene_sphere(10.0, 0.0);
        body.pose = world.root_pose;
        body.colliders.clear();
        let moving = world.add_scene_body(body);
        world
            .set_scene_body_kinematic_motion(moving, Some((Vector3::x() * 0.2, Vector3::zeros())))
            .unwrap();
        world
            .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                link: 1,
                link_point: [0.0; 3],
                body: moving,
                body_point: [0.0; 3],
            }])
            .unwrap();
        let gpu = GpuContactDevice::new_with_backends(wgpu::Backends::VULKAN).unwrap();
        let mut session =
            crate::gpu_scene_dynamics::GpuSceneDynamics::new(&world, &gpu, 0.001).unwrap();
        let _ = session.step(&mut world, &[0.0], 50).unwrap();
        let _ = session.step(&mut world, &[0.0], 50).unwrap();
        assert!((world.positions[0] - 0.02).abs() < 1e-5);
        assert!((world.velocities[0] - 0.2).abs() < 1e-5);
        assert!((world.scene_bodies[moving].pose.translation.vector.x - 0.02).abs() < 1e-5);
        world
            .set_scene_body_kinematic_motion(moving, Some((Vector3::x() * 0.3, Vector3::zeros())))
            .unwrap();
        assert!(matches!(
            session.step(&mut world, &[0.0], 1),
            Err(crate::gpu_scene_dynamics::GpuSceneDynamicsError::WorldChanged)
        ));
        assert!((world.positions[0] - 0.02).abs() < 1e-5);
    }

