    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_rotating_anchor_collision_transfers_offset_contact_velocity() {
        let mut worlds = Vec::new();
        for fixed in [true, false] {
            let mut world = scene_constraint_world(JointKind::Revolute);
            world.params.friction = 0.0;
            let mut anchor = scene_sphere(10.0, 0.0);
            anchor.colliders = vec![SceneCollider::Sphere {
                center: Vector3::x(),
                radius: 0.5,
            }];
            let moving = world.add_scene_body(anchor);
            let mut target = scene_sphere(10.0, 1.0);
            target.pose.translation.vector.x = 1.0;
            target.pose.translation.vector.y = 1.0;
            let _ = world.add_scene_body(target);
            world
                .set_scene_body_kinematic_motion(
                    moving,
                    Some((Vector3::zeros(), Vector3::z() * 0.2)),
                )
                .unwrap();
            if fixed {
                world
                    .set_link_scene_fixed_constraints(vec![LinkSceneFixedConstraint {
                        link: 1,
                        link_frame: Isometry3::identity(),
                        body: moving,
                        body_frame: Isometry3::identity(),
                    }])
                    .unwrap();
            } else {
                world
                    .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                        link: 1,
                        link_point: [1.0, 0.0, 0.0],
                        body: moving,
                        body_point: [1.0, 0.0, 0.0],
                    }])
                    .unwrap();
            }
            worlds.push(world);
        }
        let gpu = GpuContactDevice::new_with_backends(wgpu::Backends::VULKAN).unwrap();
        let mut session =
            crate::gpu_scene_dynamics::GpuSceneDynamicsBatch::new(&worlds, &gpu, 0.001).unwrap();
        let _ = session.step(&mut worlds, &[&[0.0], &[0.0]], 1).unwrap();
        for world in &worlds {
            let target = &world.scene_bodies[1];
            assert!((target.linear_velocity.y - 0.2).abs() < 1e-4, "{target:?}");
            assert!(target.linear_velocity.x.abs() < 1e-4);
            assert!(target.angular_velocity.norm() < 1e-5);
        }
        let _ = session.step(&mut worlds, &[&[0.0], &[0.0]], 99).unwrap();
        for world in &worlds {
            assert!((world.positions[0] - 0.02).abs() < 1e-5);
            assert!((world.velocities[0] - 0.2).abs() < 5e-5);
            assert!((world.scene_bodies[0].pose.rotation.scaled_axis().z - 0.02).abs() < 1e-5);
            assert!((world.scene_bodies[1].pose.translation.vector.y - 1.02).abs() < 1e-4);
            assert!(world.scene_bodies[1].angular_velocity.norm() < 1e-5);
        }
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_batch_anchor_collision_preserves_environment_and_body_mapping() {
        let speeds = [0.2_f64, 0.0, -0.1];
        let mut worlds = Vec::new();
        let mut mapping = Vec::new();
        for (environment, speed) in speeds.iter().copied().enumerate() {
            let mut world = scene_constraint_world(JointKind::Prismatic);
            let anchor = scene_sphere(10.0, 0.0);
            let mut target = scene_sphere(10.0, 1.0 + environment as f64);
            let direction = if speed < 0.0 { -1.0 } else { 1.0 };
            target.pose.translation.vector.x = direction;
            let (moving, target) = if environment == 2 {
                let target = world.add_scene_body(target);
                (world.add_scene_body(anchor), target)
            } else {
                (world.add_scene_body(anchor), world.add_scene_body(target))
            };
            world
                .set_scene_body_kinematic_motion(
                    moving,
                    Some((Vector3::x() * speed, Vector3::zeros())),
                )
                .unwrap();
            world
                .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                    link: 1,
                    link_point: [0.0; 3],
                    body: moving,
                    body_point: [0.0; 3],
                }])
                .unwrap();
            mapping.push((moving, target, direction));
            worlds.push(world);
        }
        let gpu = GpuContactDevice::new_with_backends(wgpu::Backends::VULKAN).unwrap();
        let mut session =
            crate::gpu_scene_dynamics::GpuSceneDynamicsBatch::new(&worlds, &gpu, 0.001).unwrap();
        for _ in 0..2 {
            let _ = session
                .step(&mut worlds, &[&[0.0], &[0.0], &[0.0]], 50)
                .unwrap();
        }
        for ((world, speed), (moving, target, direction)) in worlds.iter().zip(speeds).zip(mapping)
        {
            assert!((world.positions[0] - speed * 0.1).abs() < 1e-5);
            assert!((world.velocities[0] - speed).abs() < 1e-5);
            assert!(
                (world.scene_bodies[moving].pose.translation.vector.x - speed * 0.1).abs() < 1e-5
            );
            assert!((world.scene_bodies[target].linear_velocity.x - speed).abs() < 1e-4);
            assert!(
                (world.scene_bodies[target].pose.translation.vector.x - direction - speed * 0.1)
                    .abs()
                    < 1e-4
            );
            assert!(world.scene_bodies[target].angular_velocity.norm() < 1e-5);
            assert!((world.scene_bodies[target].pose.translation.vector.z - 10.0).abs() < 1e-5);
        }
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn resident_impossible_anchor_fault_preserves_world_and_rebuilds() {
        let mut world = scene_constraint_world(JointKind::Prismatic);
        let mut body = scene_sphere(10.0, 0.0);
        body.pose = world.root_pose;
        body.colliders.clear();
        let moving = world.add_scene_body(body);
        world
            .set_scene_body_kinematic_motion(moving, Some((Vector3::x() * 0.2, Vector3::zeros())))
            .unwrap();
        world
            .set_link_scene_point_constraints(vec![LinkScenePointConstraint {
                link: 0,
                link_point: [0.0; 3],
                body: moving,
                body_point: [0.0; 3],
            }])
            .unwrap();
        let gpu = GpuContactDevice::new_with_backends(wgpu::Backends::VULKAN).unwrap();
        let mut session =
            crate::gpu_scene_dynamics::GpuSceneDynamics::new(&world, &gpu, 0.001).unwrap();
        let before_positions = world.positions.clone();
        let before_pose = world.scene_bodies[moving].pose;
        assert!(session.step(&mut world, &[0.0], 1).is_err());
        assert_eq!(world.positions, before_positions);
        assert_eq!(world.scene_bodies[moving].pose, before_pose);
        assert!(matches!(
            session.step(&mut world, &[0.0], 1),
            Err(crate::gpu_scene_dynamics::GpuSceneDynamicsError::Faulted)
        ));
        world.set_scene_body_kinematic_motion(moving, None).unwrap();
        let mut recovered =
            crate::gpu_scene_dynamics::GpuSceneDynamics::new(&world, &gpu, 0.001).unwrap();
        let _ = recovered.step(&mut world, &[0.0], 10).unwrap();
        assert_eq!(world.positions, before_positions);
        assert_eq!(world.scene_bodies[moving].pose, before_pose);
    }

