    #[test]
    fn external_anchor_body_export_preserves_constraint_order() {
        let mut world = scene_constraint_world(JointKind::Prismatic);
        let dynamic = world.add_scene_body(scene_sphere(10.0, 1.0));
        let moving = world.add_scene_body(scene_sphere(10.0, 0.0));
        world
            .set_scene_body_kinematic_motion(moving, Some((Vector3::z() * 0.2, Vector3::y() * 0.3)))
            .unwrap();
        world
            .set_link_point_constraints(vec![LinkPointConstraint {
                link_a: 1,
                point_a: [0.0; 3],
                link_b: None,
                point_b: [0.0; 3],
            }])
            .unwrap();
        world
            .set_link_scene_point_constraints(vec![
                LinkScenePointConstraint {
                    link: 1,
                    link_point: [0.0; 3],
                    body: dynamic,
                    body_point: [0.0; 3],
                },
                LinkScenePointConstraint {
                    link: 1,
                    link_point: [0.0; 3],
                    body: moving,
                    body_point: [0.0; 3],
                },
            ])
            .unwrap();
        world
            .set_link_scene_fixed_constraints(vec![LinkSceneFixedConstraint {
                link: 1,
                link_frame: Isometry3::identity(),
                body: moving,
                body_frame: Isometry3::identity(),
            }])
            .unwrap();
        let exported = world.gpu_external_constraint_bodies().unwrap();
        assert_eq!(exported.len(), 3);
        assert!(exported[0].is_none());
        for entry in &exported[1..] {
            let body = entry.as_ref().unwrap();
            assert_eq!(body.pose, world.scene_bodies[moving].pose);
            assert_eq!(body.linear_velocity, Vector3::z() * 0.2);
            assert_eq!(body.angular_velocity, Vector3::y() * 0.3);
        }
    }

