    #[test]
    fn link_scene_fixed_constraint_couples_all_six_floating_axes() {
        let articulation = Articulation::new(
            vec![LinkSpec {
                mass: 1.0,
                center_of_mass: Vector3::zeros(),
                inertia: Matrix3::identity() * 0.1,
            }],
            Vec::new(),
            0,
        )
        .unwrap();
        let mut world = ArticulatedWorld::new_floating(
            articulation,
            Isometry3::translation(0.0, 0.0, 10.0),
            Vec::new(),
            ArticulatedWorldParams {
                gravity: [0.0; 3],
                ..Default::default()
            },
        )
        .unwrap();
        let body = world.add_scene_body(scene_sphere(10.0, 1.0));
        world
            .set_link_scene_fixed_constraints(vec![LinkSceneFixedConstraint {
                link: 0,
                link_frame: Isometry3::identity(),
                body,
                body_frame: Isometry3::identity(),
            }])
            .unwrap();
        world.base_linear_velocity = Vector3::new(1.0, -2.0, 3.0);
        world.base_angular_velocity = Vector3::new(0.1, -0.2, 0.3);
        #[cfg(feature = "gpu-contact")]
        let snapshot = world.snapshot();
        world.step(0.001, &[]).unwrap();
        assert!(
            (world.base_linear_velocity - world.scene_bodies[body].linear_velocity).norm() < 1e-8
        );
        assert!(
            (world.base_angular_velocity - world.scene_bodies[body].angular_velocity).norm() < 1e-8
        );
        #[cfg(feature = "gpu-contact")]
        if let Ok(gpu) = GpuContactDevice::new() {
            let expected_linear = world.scene_bodies[body].linear_velocity;
            let expected_angular = world.scene_bodies[body].angular_velocity;
            world.restore_snapshot(&snapshot).unwrap();
            world.step_gpu(0.001, &[], &gpu).unwrap();
            assert!((world.scene_bodies[body].linear_velocity - expected_linear).norm() < 1e-5);
            assert!((world.scene_bodies[body].angular_velocity - expected_angular).norm() < 1e-5);
        }
    }

