    #[test]
    fn stiff_passive_spring_dissipates_energy_with_implicit_step() {
        let mut world = pendulum();
        world.params.gravity = [0.0; 3];
        world.positions[0] = 0.5;
        let stiffness = 1.0e6;
        world
            .set_joint_passive(
                0,
                JointPassive {
                    stiffness,
                    damping: 0.0,
                    rest_position: 0.0,
                },
            )
            .unwrap();
        let inertia = world
            .articulation
            .dynamics(
                &world
                    .articulation
                    .pose(world.root_pose, world.positions.as_slice())
                    .unwrap(),
                Vector3::zeros(),
            )
            .unwrap()
            .mass[(0, 0)];
        let mut energy = 0.5 * stiffness * world.positions[0].powi(2);
        for _ in 0..100 {
            world.step(0.001, &[0.0]).unwrap();
            let next = 0.5 * inertia * world.velocities[0].powi(2)
                + 0.5 * stiffness * world.positions[0].powi(2);
            assert!(next <= energy + 1e-8);
            energy = next;
        }
    }

    #[test]
    fn joint_motor_caps_its_force_and_resets_with_snapshot() {
        let mut driven = pendulum();
        let mut reference = pendulum();
        driven.params.gravity = [0.0; 3];
        reference.params.gravity = [0.0; 3];
        let motor = JointMotor {
            position_target: Some(1.0),
            velocity_target: 0.0,
            stiffness: 100.0,
            damping: 0.0,
            max_force: 0.2,
        };
        driven.set_joint_motor(0, Some(motor)).unwrap();
        assert_eq!(driven.joint_motor(0), Some(motor));
        assert!(driven.set_joint_motor(1, Some(motor)).is_err());
        assert!(
            driven
                .set_joint_motor(
                    0,
                    Some(JointMotor {
                        stiffness: f64::NAN,
                        ..motor
                    }),
                )
                .is_err()
        );
        assert_eq!(driven.joint_motor(0), Some(motor));
        let snapshot = driven.snapshot();
        driven.step(0.001, &[0.0]).unwrap();
        reference.step(0.001, &[0.2]).unwrap();
        assert!((&driven.positions - &reference.positions).norm() < 1e-12);
        assert!((&driven.velocities - &reference.velocities).norm() < 1e-12);
        driven.set_joint_motor(0, None).unwrap();
        driven.restore_snapshot(&snapshot).unwrap();
        assert_eq!(driven.joint_motor(0), Some(motor));
        assert_eq!(driven.positions[0], 0.0);
    }

