    #[test]
    fn self_contacts_can_be_disabled_and_restored_from_snapshot() {
        let mut world = self_colliding_tree();
        assert!(world.self_contacts_enabled());
        let enabled = world.snapshot();
        world.set_self_contacts_enabled(false);
        assert!(!world.self_contacts_enabled());
        world.step(0.001, &[0.0]).unwrap();
        assert!(world.positions[0].abs() < 1e-12);
        assert!(
            world
                .contact_forces
                .iter()
                .all(|force| force.norm() < 1e-12)
        );
        world.restore_snapshot(&enabled).unwrap();
        assert!(world.self_contacts_enabled());
        world.step(0.001, &[0.0]).unwrap();
        assert!(world.positions[0] < 0.0);
    }

