    #[cfg(feature = "gpu-contact")]
    fn convex_convex_tree() -> ArticulatedWorld {
        let mut world = box_convex_tree();
        world.boxes.clear();
        let mut other = world.convex_shapes[0].clone();
        other.link = 1;
        world
            .set_convex_shapes(vec![other, world.convex_shapes[0].clone()])
            .unwrap();
        world
    }

    #[cfg(feature = "gpu-contact")]
    fn tetra_convex_tree() -> ArticulatedWorld {
        let mut world = box_convex_tree();
        let vertices = vec![
            Vector3::new(0.0, 0.0, -0.2),
            Vector3::new(-0.2, -0.2, 0.2),
            Vector3::new(0.2, -0.2, 0.2),
            Vector3::new(0.0, 0.2, 0.2),
        ];
        let center = vertices.iter().copied().sum::<Vector3<f64>>() / vertices.len() as f64;
        let faces = [(1, 2, 3), (0, 3, 2), (0, 1, 3), (0, 2, 1)];
        let normals = faces
            .into_iter()
            .map(|(a, b, c)| {
                let direction = (vertices[b] - vertices[a]).cross(&(vertices[c] - vertices[a]));
                let outward = if direction.dot(&(center - vertices[a])) > 0.0 {
                    -direction
                } else {
                    direction
                };
                outward.normalize()
            })
            .collect();
        let edges = (0..vertices.len())
            .flat_map(|a| (a + 1..vertices.len()).map(move |b| (a, b)))
            .map(|(a, b)| (vertices[b] - vertices[a]).normalize())
            .collect();
        world.convex_shapes[0].geometry = ConvexGeometry::new(vertices, normals, edges).unwrap();
        world
    }

    #[cfg(feature = "gpu-contact")]
    fn hexagonal_convex_tree() -> ArticulatedWorld {
        let mut world = box_convex_tree();
        let angle = core::f64::consts::TAU / 6.0;
        let vertices = [-0.2, 0.2]
            .into_iter()
            .flat_map(|x| {
                (0..6).map(move |index| {
                    let phase = index as f64 * angle;
                    Vector3::new(x, 0.2 * phase.cos(), 0.2 * phase.sin())
                })
            })
            .collect();
        let mut normals = vec![Vector3::x(), -Vector3::x()];
        let mut edges = vec![Vector3::x()];
        for index in 0..6 {
            let phase = (index as f64 + 0.5) * angle;
            normals.push(Vector3::new(0.0, phase.cos(), phase.sin()));
            edges.push(Vector3::new(0.0, -phase.sin(), phase.cos()));
        }
        world.convex_shapes[0].geometry = ConvexGeometry::new(vertices, normals, edges).unwrap();
        world
    }

