    #[cfg(feature = "gpu-contact")]
    #[test]
    fn fixed_root_world_gpu_convex_sphere_self_contact() {
        use crate::gpu_articulated_dynamics::GpuArticulatedDynamicsBatch;

        let mut tested = 0;
        for backend in [wgpu::Backends::VULKAN, wgpu::Backends::DX12] {
            let Ok(context) = GpuContactDevice::new_with_backends(backend) else {
                continue;
            };
            tested += 1;
            let mut cpu = sphere_convex_tree();
            let actual = sphere_convex_tree();
            let input = actual.gpu_dynamics_input(&[0.0]).unwrap();
            assert_eq!(input.convex_sphere_pairs.len(), 1);
            assert_eq!(input.convex_sphere_pairs[0].convex_link, 2);
            assert_eq!(input.convex_sphere_pairs[0].sphere_link, 1);
            let batch = GpuArticulatedDynamicsBatch::new(&context, &[input], 0.001).unwrap();
            batch.submit_steps(1).unwrap();
            let gpu_velocity = batch.readback().unwrap()[0].velocities[0];
            cpu.step(0.001, &[0.0]).unwrap();
            assert!(gpu_velocity.abs() > 0.01);
            assert!(
                (gpu_velocity - cpu.velocities[0]).abs() < 0.1,
                "gpu {gpu_velocity}, cpu {}",
                cpu.velocities[0]
            );

            let mut inside = sphere_convex_tree();
            inside.colliders[0].center.z = -0.25;
            let mut cpu = sphere_convex_tree();
            cpu.colliders[0].center.z = -0.25;
            let input = inside.gpu_dynamics_input(&[0.0]).unwrap();
            let batch = GpuArticulatedDynamicsBatch::new(&context, &[input], 0.001).unwrap();
            batch.submit_steps(1).unwrap();
            let gpu_velocity = batch.readback().unwrap()[0].velocities[0];
            cpu.step(0.001, &[0.0]).unwrap();
            assert!(gpu_velocity.is_finite() && gpu_velocity.abs() > 0.01);
            assert!(
                (gpu_velocity - cpu.velocities[0]).abs() < 0.2,
                "inside hull: gpu {gpu_velocity}, cpu {}",
                cpu.velocities[0]
            );

            let mut separated = sphere_convex_tree();
            separated.colliders[0].center.x += 2.0;
            let input = separated.gpu_dynamics_input(&[0.0]).unwrap();
            let batch = GpuArticulatedDynamicsBatch::new(&context, &[input], 0.001).unwrap();
            batch.submit_steps(1).unwrap();
            assert!(batch.readback().unwrap()[0].velocities[0].abs() < 1e-6);

            let touching = sphere_convex_tree();
            let inputs = [
                touching.gpu_dynamics_input(&[0.0]).unwrap(),
                separated.gpu_dynamics_input(&[0.0]).unwrap(),
            ];
            let batch = GpuArticulatedDynamicsBatch::new(&context, &inputs, 0.001).unwrap();
            batch.submit_steps(1).unwrap();
            let states = batch.readback().unwrap();
            assert!(states[0].velocities[0].abs() > 0.01);
            assert!(states[1].velocities[0].abs() < 1e-6);

            let mut moving_hull = sphere_convex_tree();
            moving_hull.convex_shapes[0].link = 1;
            moving_hull.convex_shapes[0].origin = Isometry3::translation(1.0, 0.0, 0.0)
                * Isometry3::rotation(Vector3::y() * core::f64::consts::FRAC_PI_4);
            moving_hull.colliders[0].link = 2;
            let mut cpu = sphere_convex_tree();
            cpu.convex_shapes[0].link = 1;
            cpu.convex_shapes[0].origin = moving_hull.convex_shapes[0].origin;
            cpu.colliders[0].link = 2;
            let input = moving_hull.gpu_dynamics_input(&[0.0]).unwrap();
            let batch = GpuArticulatedDynamicsBatch::new(&context, &[input], 0.001).unwrap();
            batch.submit_steps(1).unwrap();
            let gpu_velocity = batch.readback().unwrap()[0].velocities[0];
            cpu.step(0.001, &[0.0]).unwrap();
            assert!(gpu_velocity.abs() > 0.01);
            assert!(
                (gpu_velocity - cpu.velocities[0]).abs() < 0.1,
                "rotated hull: gpu {gpu_velocity}, cpu {}",
                cpu.velocities[0]
            );
        }
        assert!(tested > 0);
        let mut filtered = sphere_convex_tree();
        filtered.set_self_contacts_enabled(false);
        assert!(
            filtered
                .gpu_dynamics_input(&[0.0])
                .unwrap()
                .convex_sphere_pairs
                .is_empty()
        );
    }

