    #[cfg(feature = "gpu-contact")]
    #[test]
    fn fixed_root_world_gpu_scene_mesh_and_heightfield_contact_link_axial() {
        use crate::gpu_articulated_dynamics::GpuArticulatedDynamicsBatch;

        let build = |kind: GpuArticulatedGroundAxialKind,
                     heightfield: bool,
                     rotation: f64,
                     separation: f64| {
            let mut world = box_convex_tree();
            world.boxes.clear();
            world.convex_shapes.clear();
            let local_pose = Isometry3::translation(1.0, 0.0, 0.0)
                * Isometry3::rotation(Vector3::y() * rotation);
            match kind {
                GpuArticulatedGroundAxialKind::Cylinder => world
                    .set_cylinders(vec![LinkCylinder {
                        link: 1,
                        origin: local_pose,
                        half_height: 0.2,
                        radius: 0.2,
                    }])
                    .unwrap(),
                GpuArticulatedGroundAxialKind::Cone => world
                    .set_cones(vec![LinkCone {
                        link: 1,
                        origin: local_pose,
                        half_height: 0.2,
                        radius: 0.2,
                    }])
                    .unwrap(),
            }
            world.colliders.push(LinkSphere {
                link: 1,
                center: Vector3::new(100.0, 0.0, 0.0),
                radius: 0.2,
            });
            let center = world.link_poses().unwrap()[1]
                .transform_point(&Point3::new(1.0, 0.0, 0.0))
                .coords;
            let (offset_x, collider) = if heightfield {
                (
                    0.5,
                    SceneCollider::HeightField {
                        origin: Isometry3::identity(),
                        geometry: HeightFieldGeometry::new(
                            32,
                            32,
                            vec![0.0; 32 * 32],
                            Vector3::new(4.0, 4.0, 1.0),
                        )
                        .unwrap(),
                    },
                )
            } else {
                (
                    0.0,
                    SceneCollider::TriangleMesh {
                        origin: Isometry3::identity(),
                        geometry: TriangleMeshGeometry::new(
                            vec![
                                Vector3::new(-1.0, -1.0, 0.0),
                                Vector3::new(1.0, -1.0, 0.0),
                                Vector3::new(0.0, 1.0, 0.0),
                            ],
                            vec![[0, 1, 2]],
                        )
                        .unwrap(),
                    },
                )
            };
            let _ = world.add_scene_body(
                SceneBody::new(
                    Isometry3::translation(center.x + offset_x, center.y, center.z + separation),
                    0.0,
                    Matrix3::zeros(),
                    vec![collider],
                )
                .unwrap(),
            );
            world
        };
        let cases = [
            (GpuArticulatedGroundAxialKind::Cylinder, false, 0.0, 0.1),
            (GpuArticulatedGroundAxialKind::Cone, false, 0.0, 0.1),
            (GpuArticulatedGroundAxialKind::Cylinder, false, 0.6, 0.1),
            (GpuArticulatedGroundAxialKind::Cylinder, true, 0.0, 0.1),
            (GpuArticulatedGroundAxialKind::Cylinder, false, 0.0, 2.0),
        ];
        let worlds = cases.map(|(kind, heightfield, rotation, separation)| {
            build(kind, heightfield, rotation, separation)
        });
        let inputs = worlds
            .iter()
            .map(|world| world.gpu_dynamics_input(&[0.0]).unwrap())
            .collect::<Vec<_>>();
        for input in &inputs {
            assert_eq!(input.scene_mesh_axial_pairs.len(), 1);
            assert_eq!(input.scene_mesh_sphere_pairs.len(), 1);
            assert!(Arc::ptr_eq(
                &input.scene_mesh_axial_pairs[0].mesh,
                &input.scene_mesh_sphere_pairs[0].mesh
            ));
            assert!(input.static_axial_convex_pairs.is_empty());
        }
        let mut flat_cpu = build(GpuArticulatedGroundAxialKind::Cylinder, true, 0.0, 0.1);
        let contacts = flat_cpu.prepare_contact_step(0.001, &[0.0], None).unwrap();
        assert!(!contacts.contact_frames.is_empty());
        assert!(
            contacts
                .contact_frames
                .iter()
                .all(|contact| contact.normal.z > 0.9)
        );
        flat_cpu.step(0.001, &[0.0]).unwrap();
        assert!(flat_cpu.velocities[0] > 0.01);

        let mut tested = 0;
        for backend in [wgpu::Backends::VULKAN, wgpu::Backends::DX12] {
            let Ok(context) = GpuContactDevice::new_with_backends(backend) else {
                continue;
            };
            tested += 1;
            let batch = GpuArticulatedDynamicsBatch::new(&context, &inputs, 0.001).unwrap();
            batch.submit_steps(1).unwrap();
            let states = batch.readback().unwrap();
            for (index, (kind, heightfield, rotation, separation)) in cases.into_iter().enumerate()
            {
                let mut cpu = build(kind, heightfield, rotation, separation);
                cpu.step(0.001, &[0.0]).unwrap();
                let gpu_velocity = states[index].velocities[0];
                if index == 4 {
                    assert!((gpu_velocity - cpu.velocities[0]).abs() < 1e-3);
                } else if heightfield {
                    assert!(gpu_velocity > 0.01, "case {index}: {gpu_velocity}");
                } else {
                    assert!(gpu_velocity.is_finite());
                    assert!(gpu_velocity > 0.01, "case {index}: {gpu_velocity}");
                    if cpu.velocities[0].abs() > 0.01 {
                        assert!(
                            gpu_velocity * cpu.velocities[0] > 0.0,
                            "case {index}: gpu {gpu_velocity}, cpu {}",
                            cpu.velocities[0]
                        );
                    }
                }
            }
        }
        assert!(tested > 0);
    }

