    #[cfg(feature = "gpu-contact")]
    #[test]
    fn gpu_robot_lbvh_preserves_convex_contacts_with_many_distant_spheres() {
        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        for make_world in [
            sphere_convex_tree as fn() -> ArticulatedWorld,
            box_convex_tree,
        ] {
            let with_distant_spheres = || {
                let mut world = make_world();
                for index in 0..64 {
                    world.colliders.push(LinkSphere {
                        link: 2,
                        center: Vector3::new(100.0 + f64::from(index) * 2.0, 0.0, 0.0),
                        radius: 0.2,
                    });
                }
                world
            };
            let mut reference = with_distant_spheres();
            let mut actual = with_distant_spheres();
            reference.step(0.001, &[0.0]).unwrap();
            actual.step_gpu(0.001, &[0.0], &gpu).unwrap();
            assert!((actual.positions[0] - reference.positions[0]).abs() < 1e-6);
            assert!((actual.contact_forces[1] - reference.contact_forces[1]).norm() < 1e-2);
        }
    }

