    #[test]
    fn four_ground_points_support_floating_body() {
        let mut world = floating_box_points();
        world.step(0.02, &[]).unwrap();
        assert!((world.root_pose.translation.vector.z - 0.5).abs() < 1e-3);
        assert!(world.contact_forces[0].z > 9.0);
    }

    #[test]
    fn four_ground_points_support_floating_body_over_time() {
        let mut world = floating_box_points();
        world.params.max_substep = 0.01;
        for _ in 0..1000 {
            world.step(0.01, &[]).unwrap();
        }
        assert!((world.root_pose.translation.vector.z - 0.5).abs() < 0.01);
        assert!(world.base_linear_velocity.norm() < 0.1);
        assert!(world.base_angular_velocity.norm() < 0.1);
    }

    #[cfg(feature = "gpu-contact")]
    #[test]
    fn gpu_ground_points_match_cpu_reference() {
        let Ok(gpu) = GpuContactDevice::new() else {
            return;
        };
        let mut reference = floating_box_points();
        let mut actual = floating_box_points();
        reference.step(0.02, &[]).unwrap();
        actual.step_gpu(0.02, &[], &gpu).unwrap();
        assert!(
            (actual.root_pose.translation.vector - reference.root_pose.translation.vector).norm()
                < 1e-4
        );
    }
